PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE correos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  message_id   TEXT,
  de           TEXT,                       -- remitente (from)
  para         TEXT,                       -- destinatario (to)
  asunto       TEXT,
  cuerpo_texto TEXT,
  cuerpo_html  TEXT,
  dominio      TEXT,                        -- derivado de 'para' (multi-dominio futuro)
  estado       TEXT DEFAULT 'nuevo',        -- nuevo | leido (respondido en fases siguientes)
  recibido_en  TEXT,                        -- fecha del correo (ISO)
  creado_en    TEXT DEFAULT (datetime('now'))
, respuesta_borrador TEXT, respuesta_enviada  TEXT, respondido_en      TEXT, adjunto_nombre TEXT, adjunto_b64    TEXT, notificado INTEGER DEFAULT 0, ajuste_pedido TEXT, ajuste_enviar INTEGER DEFAULT 0, confianza TEXT, motivo_revision TEXT, dedup_hash  TEXT, thread_id   TEXT, in_reply_to TEXT, referencias TEXT, leido       INTEGER NOT NULL DEFAULT 0, estado_previo TEXT, etiquetas TEXT, estado_prev_papelera TEXT);
CREATE TABLE push_subs (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  endpoint  TEXT UNIQUE,
  p256dh    TEXT,
  auth      TEXT,
  creado_en TEXT DEFAULT (datetime('now'))
);
CREATE TABLE bloqueados (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  tipo      TEXT NOT NULL,                       -- 'email' | 'dominio'
  valor     TEXT NOT NULL,                       -- lower-case: email completo o dominio del REMITENTE
  motivo    TEXT,                                -- obligatorio desde el panel (R8)
  creado_en TEXT DEFAULT (datetime('now')),
  UNIQUE(tipo, valor)
);
CREATE TABLE aprendizaje (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  senal     TEXT NOT NULL,                       -- 'spam' | 'legit' | 'bloqueo' | 'desbloqueo'
  remitente TEXT,                                -- email lower-case
  dominio   TEXT,                                -- dominio del remitente lower-case
  motivo    TEXT,                                -- razón dada por el dueño
  correo_id INTEGER,                             -- correo origen (NULL si no aplica)
  creado_en TEXT DEFAULT (datetime('now'))
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_correos_recibido ON correos(recibido_en DESC);
CREATE INDEX idx_correos_dominio  ON correos(dominio);
CREATE INDEX idx_bloqueados_valor ON bloqueados(valor);
CREATE INDEX idx_aprendizaje_remitente ON aprendizaje(remitente);
CREATE INDEX idx_aprendizaje_dominio   ON aprendizaje(dominio);
CREATE UNIQUE INDEX idx_correos_mid_uniq ON correos(message_id)
  WHERE message_id IS NOT NULL AND message_id <> '';
CREATE INDEX idx_correos_dedup_hash  ON correos(dedup_hash);
CREATE INDEX idx_correos_orden       ON correos(recibido_en DESC, id DESC);
CREATE INDEX idx_correos_thread      ON correos(thread_id);
CREATE INDEX idx_correos_estado_fecha ON correos(estado, recibido_en DESC);
