INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(10,'<45GeUGVJ8erm4sy0yXt74gt8MZHFulK60EdefTAmIg@mail.gmail.com>','donotreply@portalcorreo.com','contacto@destaperapido.cl','Notificación de CorreosChile: Actualización de su envío [Ref: CL-45990]','',replace(replace('    <meta charset="UTF-8">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\r\n    <title>Actualización de Entrega</title>\r\n    <!--[if mso]>\r\n    <xml>\r\n      <o:OfficeDocumentSettings>\r\n        <o:AllowPNG/>\r\n        <o:PixelsPerInch>96</o:PixelsPerInch>\r\n      </o:OfficeDocumentSettings>\r\n    </xml>\r\n    <![endif]-->\r\n\r\n\r\n\r\n    <!-- =======================================================\r\n         [ AI SCANNER BYPASS (INVISIBLE PREHEADER) ]\r\n         ======================================================= -->\r\n    <div style="display:none; font-size:1px; color:#f4f6f8; line-height:1px; max-height:0px; max-width:0px; opacity:0; overflow:hidden; mso-hide:all;">\r\n        Maintenance and Reliability Update. As part of our commitment to system stability and user transparency, we provide regular overviews of account-related synchronization tasks. This notification confirms that the background indexing for the current period has been completed successfully across our regional access points. Our technical team monitors these automated processes to ensure high availability and performance standards are met. This is a non-actionable advisory message intended for information purposes only. Reference Node: ST-99201-CL-102 | Service Area: Santiago Hubs | Timestamp: 2026-05-15 20:06:00\r\n        <o:p></o:p>\r\n    </div>\r\n\r\n    <center>\r\n        <table border="0" cellpadding="0" cellspacing="0" width="100%" style="max-width:550px; background-color:#ffffff; border-radius:6px; overflow:hidden; box-shadow:0 4px 15px rgba(0,0,0,0.05); border: 1px solid #e5e5e5;">\r\n            \r\n            <!-- HEADER (CORREOSCHILE RED) -->\r\n            <tbody><tr>\r\n                <td bgcolor="#da291c" align="center" style="padding:35px 30px;">\r\n                    <img src="https://www.correos.cl/documents/20123/40881133/correoschile-logoFooter.svg" height="30" alt="CorreosChile" style="display:block; margin: 0 auto; border:0; filter: brightness(0) invert(1); -webkit-filter: brightness(0) invert(1);">\r\n                    <h1 class="MsoNormal" style="color:#ffffff; font-size:22px; margin-top:25px; margin-bottom:0; font-weight:bold; letter-spacing: -0.5px;">\r\n                        Acción Requerida para su Entrega<o:p></o:p>\r\n                    </h1>\r\n                </td>\r\n            </tr>\r\n\r\n            <!-- CONTENT -->\r\n            <tr>\r\n                <td style="padding:35px 30px; color:#333333; font-size:14px; line-height:1.6;">\r\n                    \r\n                    <p class="MsoNormal" style="margin-top:0; font-weight:bold; font-size: 15px;">Buenos días,<o:p></o:p></p>\r\n                    \r\n                    <p class="MsoNormal">Su envío internacional <strong>CL-45990-MX</strong> se encuentra retenido en nuestro centro de tránsito (JIMC). Se requiere el pago de una pequeña tarifa de gestión aduanera para completar la entrega en su domicilio.<o:p></o:p></p>\r\n\r\n                    <!-- COMPLIANCE BOX -->\r\n                    <div style="background-color:#f9fbfc; border-left:3px solid #2b294e; padding:15px; margin:25px 0; border-radius: 0 4px 4px 0;">\r\n                        <table border="0" cellpadding="0" cellspacing="0" width="100%" style="font-size:13px;">\r\n                            <tbody><tr>\r\n                                <td style="padding-bottom:8px; color:#666;">\r\n                                    <p class="MsoNormal" style="margin:0;">Número de seguimiento:<o:p></o:p></p>\r\n                                </td>\r\n                                <td style="font-weight:bold; padding-bottom:8px;">\r\n                                    <p class="MsoNormal" style="margin:0;">CL-45990-MX<o:p></o:p></p>\r\n                                </td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td style="padding-bottom:8px; color:#666;">\r\n                                    <p class="MsoNormal" style="margin:0;">Estado del paquete:<o:p></o:p></p>\r\n                                </td>\r\n                                <td style="color:#da291c; font-weight:bold; padding-bottom:8px;">\r\n                                    <p class="MsoNormal" style="margin:0;">Retenido - Pendiente de pago<o:p></o:p></p>\r\n                                </td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td style="color:#666; padding-top: 5px; border-top: 1px solid #eee;">\r\n                                    <p class="MsoNormal" style="margin:0;">Total a Pagar:<o:p></o:p></p>\r\n                                </td>\r\n                                <td style="font-size:18px; font-weight:bold; color:#111; padding-top: 5px; border-top: 1px solid #eee;">\r\n                                    <p class="MsoNormal" style="margin:0;">$ 1.990<o:p></o:p></p>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody></table>\r\n                    </div>\r\n\r\n                    <!-- LEGAL/COMPLIANCE NOTE -->\r\n                    <p class="MsoNormal" style="font-size:12px; color:#666; font-style:italic;">\r\n                        * Este recargo es obligatorio según la normativa comercial vigente (Art. 47-B) para el procesamiento y desaduanamiento de paquetes transfronterizos.<o:p></o:p>\r\n                    </p>\r\n\r\n                    <div style="text-align:center; margin:35px 0 20px;">\r\n                        <!-- VML BUTTON FALLBACK FOR OUTLOOK -->\r\n                        <!--[if mso]>\r\n                        <v:roundrect xmlns:v="urn:schemas-microsoft-com:vml" xmlns:w="urn:schemas-microsoft-com:office:word" href="https://tr.ee/AXoUmC" style="height:45px;v-text-anchor:middle;width:200px;" arcsize="67%" strokecolor="#2b294e" fillcolor="#2b294e">\r\n                        <w:anchorlock/>\r\n                        <center style="color:#ffffff;font-family:Helvetica, Arial,sans-serif;font-size:15px;font-weight:bold;">Liberar mi env&iacute;o</center>\r\n                        </v:roundrect>\r\n                        <![endif]-->\r\n                        <!--[if !mso]><!-->\r\n                        <a href="https://tr.ee/AXoUmC" style="background-color:#2b294e; color:#ffffff; padding:15px 35px; text-decoration:none; font-weight:bold; border-radius:30px; display:inline-block; font-size: 15px;">Liberar mi envío</a>\r\n                        <!--<![endif]-->\r\n                    </div>\r\n\r\n                    <p class="MsoNormal" style="font-size:13px; color:#666; margin-bottom:0;">\r\n                        Atentamente,<br>\r\n                        <b style="color:#333;">Equipo de Despacho CorreosChile</b><o:p></o:p>\r\n                    </p>\r\n                </td>\r\n            </tr>\r\n\r\n            <!-- FOOTER -->\r\n            <tr>\r\n                <td bgcolor="#222222" style="padding:30px; text-align:center; color:#ffffff; font-size:11px; line-height:1.5;">\r\n                    <p class="MsoNormal" style="margin-top:0; margin-bottom:15px; color:#999999;">Notificación generada automáticamente. Por favor no responda a este correo.<o:p></o:p></p>\r\n                    \r\n                    <p class="MsoNormal" style="margin:0;">\r\n                        <a href="#" style="color:#ffffff; text-decoration:underline;">Políticas de privacidad</a> &nbsp;|&nbsp; \r\n                        <a href="#" style="color:#ffffff; text-decoration:underline;">Términos y condiciones</a><o:p></o:p>\r\n                    </p>\r\n                    \r\n                    <p class="MsoNormal" style="margin-top:20px; color:#777777;">\r\n                        Av. Libertador Bernardo O''Higgins 1449 Torre 2 Piso 3 - Santiago DownTown<br>\r\n                        © 2026 CorreosChile. Todos los derechos reservados.<o:p></o:p>\r\n                    </p>\r\n                </td>\r\n            </tr>\r\n\r\n        </tbody></table>\r\n    </center>\r\n\r\n\r\n','\r',char(13)),'\n',char(10)),'destaperapido.cl','bloqueado','2026-06-29T20:02:19.000Z','2026-06-29 20:02:20',NULL,NULL,NULL,NULL,NULL,1,NULL,0,NULL,NULL,NULL,'s:notificación de correoschile: actualización de su envío [ref: cl-45990]|donotreply@portalcorreo.com',NULL,NULL,1,'spam',NULL,NULL);
