INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(19,'<003101dd08b1$18339450$489abcf0$@ggl.cl>','kyanti@ggl.cl','contacto@destaperapido.cl','738|SPP| Baños y Duchas',replace('Estimados buenas tardes.\n\n \n\nJunto con saludar, me comunico de constructora GGL para la cotización de\narriendo de:\n\n \n\n-        3 unidades de baños químicos por 2 meses.\n\n-        1 unidad de ducha química por 2 meses.\n\n \n\nSe anexan datos de constructora y de obra:\n\n \n\n-        Proyecto “Reducción de Local DOREMI – Mallplaza Norte” \n\n-        Dirección Av. Américo Vespucio Norte N.º 1737, comuna Huechuraba.\n\n-        Datos Empresa:\n\n*  INGENIERIA Y CONSTRUCCION GGL LIMITADA\n\n*  RUT N° 76.137.730-2\n\n*  Dirección Marín 0276\n\n*  Giro Construcción.\n\n \n\nQuedo atento a su respuesta.\n\n\n \n\n\n\nMarín 0276, Providencia, Santiago - Chile\n\n \n\nYanti Kevin.\n\nOficina Técnica\n\nCel: +56 9 3349 8783\n\nTel: (+562) 2635 6316\n\nRut: 76.137.730-2\n\nWeb:   <http://www.ggl.cl/> www.ggl.cl\n\n \n\n \n\n\n','\n',char(10)),replace('<html xmlns:v="urn:schemas-microsoft-com:vml" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns:m="http://schemas.microsoft.com/office/2004/12/omml" xmlns="http://www.w3.org/TR/REC-html40"><head><meta http-equiv=Content-Type content="text/html; charset=iso-8859-1"><meta name=Generator content="Microsoft Word 15 (filtered medium)"><!--[if !mso]><style>v\:* {behavior:url(#default#VML);}\no\:* {behavior:url(#default#VML);}\nw\:* {behavior:url(#default#VML);}\n.shape {behavior:url(#default#VML);}\n</style><![endif]--><style><!--\n/*