INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(355,'b8fae491-fef1-4ee1-b449-e977e6710e73','contacto@destaperapido.cl','CristianUlloaLagos@gmail.com','Cotización Destape Rápido — Arriendo de baño químico y ducha',replace('Estimado Cristian,\n\nJunto con saludar, adjunto la cotización formal por el arriendo de un baño químico y una ducha para su faena en Av. Central 999, Peñaflor.\n\nResumen comercial:\n- 1 baño químico + 1 ducha (arriendo mensual)\n- Traslado, instalación y retiro incluidos\n- Limpieza semanal (cada 7 a 10 días) incluida sin costo\n- Insumos: papel higiénico y desodorizante\n- Baño: $160.000 neto/mes · Ducha: $100.000 neto/mes\n- Total mensual: $260.000 neto · $309.400 con IVA\n- Modalidad: mensual con renovación. Pago contra entrega (efectivo o transferencia), sin adelanto.\n\nEn la cotización adjunta encontrará el detalle completo y las condiciones del servicio.\n\nQuedamos atentos para coordinar la instalación. Cualquier consulta puede escribirnos o llamarnos al +56 9 3647 0112.\n\nSaludos cordiales,\nDestape Rápido - Servicios sanitarios y arriendo de baños químicos\ndestaperapido.cl','\n',char(10)),NULL,'gmail.com','enviado','2026-07-06T14:48:42.781Z','2026-07-06 14:48:43',NULL,replace('Estimado Cristian,\n\nJunto con saludar, adjunto la cotización formal por el arriendo de un baño químico y una ducha para su faena en Av. Central 999, Peñaflor.\n\nResumen comercial:\n- 1 baño químico + 1 ducha (arriendo mensual)\n- Traslado, instalación y retiro incluidos\n- Limpieza semanal (cada 7 a 10 días) incluida sin costo\n- Insumos: papel higiénico y desodorizante\n- Baño: $160.000 neto/mes · Ducha: $100.000 neto/mes\n- Total mensual: $260.000 neto · $309.400 con IVA\n- Modalidad: mensual con renovación. Pago contra entrega (efectivo o transferencia), sin adelanto.\n\nEn la cotización adjunta encontrará el detalle completo y las condiciones del servicio.\n\nQuedamos atentos para coordinar la instalación. Cualquier consulta puede escribirnos o llamarnos al +56 9 3647 0112.\n\nSaludos cordiales,\nDestape Rápido - Servicios sanitarios y arriendo de baños químicos\ndestaperapido.cl','\n',char(10)),'2026-07-06T14:48:42.781Z','cotizacion-20260706-cristian-ulloa.pdf','',1,NULL,0,NULL,NULL,NULL,'s:cotización destape rápido — arriendo de baño químico y ducha|cristianulloalagos@gmail.com',NULL,NULL,1,NULL,NULL,NULL);
