INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(373,'6a0f64b4-3024-4b91-9738-58a609a890d6','contacto@destaperapido.cl','sebaandres260198@gmail.com','Cotización Destape Rápido — Arriendo de baño químico',replace('Hola René,\n\nJunto con saludar, adjunto la cotización del arriendo del baño químico para la obra en Cerro Lagunillas 11805, Lo Barnechea.\n\nValor mensual: $160.000 neto ($190.400 con IVA). Arriendo por 2 meses (total del período: $320.000 neto / $380.800 con IVA).\n\nIncluye traslado, instalación y retiro sin costo, más limpieza semanal (cada 7 a 10 días) y los insumos (papel higiénico y desodorizante).\n\nLa instalación quedó agendada para mañana. El primer mes se cobra al momento de la entrega (efectivo o transferencia), facturado a nombre de René Etchegaray Ponce, RUT 78.269.364-6.\n\nCualquier consulta, quedamos atentos.\n\nSaludos,\nDestape Rápido\n+56 9 3647 0112','\n',char(10)),NULL,'gmail.com','enviado','2026-07-08T03:33:54.646Z','2026-07-08 03:33:55',NULL,replace('Hola René,\n\nJunto con saludar, adjunto la cotización del arriendo del baño químico para la obra en Cerro Lagunillas 11805, Lo Barnechea.\n\nValor mensual: $160.000 neto ($190.400 con IVA). Arriendo por 2 meses (total del período: $320.000 neto / $380.800 con IVA).\n\nIncluye traslado, instalación y retiro sin costo, más limpieza semanal (cada 7 a 10 días) y los insumos (papel higiénico y desodorizante).\n\nLa instalación quedó agendada para mañana. El primer mes se cobra al momento de la entrega (efectivo o transferencia), facturado a nombre de René Etchegaray Ponce, RUT 78.269.364-6.\n\nCualquier consulta, quedamos atentos.\n\nSaludos,\nDestape Rápido\n+56 9 3647 0112','\n',char(10)),'2026-07-08T03:33:54.646Z','cotizacion-20260706-rene-etchegaray.pdf','',1,NULL,0,NULL,NULL,NULL,'s:cotización destape rápido — arriendo de baño químico|sebaandres260198@gmail.com',NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(374,'262c3a87-5cef-4902-8be7-7ef8f8e371cb','contacto@destaperapido.cl','conta@robcar.cl','Cotización Destape Rápido — Arriendo de baño químico, Colina',replace('Estimada Cristina,\n\nJunto con saludar, adjunto cotización formal por el arriendo de baño químico con lavamanos para la obra de Los Montes 1022, Colina.\n\nResumen comercial:\n- 1 baño químico con lavamanos, arriendo mensual (contrato por 2 meses)\n- Limpieza semanal (cada 7 a 10 días) incluida sin costo\n- Despacho, instalación y retiro incluidos\n- Valor mensual: $160.000 neto · $190.400 con IVA\n- Referencia contrato total 2 meses: $380.800 con IVA\n- Facturación: factura electrónica a Ingeniería Eléctrica y Construcción ROBCAR Limitada\n- Entrega: miércoles 08 de julio, desde las 11:00 AM aprox\n- Pago: efectivo o transferencia, contra entrega\n\nEn la cotización adjunta encontrarán el detalle completo, condiciones del servicio y datos de transferencia.\n\nQuedamos atentos para coordinar la instalación. Cualquier consulta no dude en escribirnos o llamarnos al +56 9 3647 0112.\n\nSaludos cordiales,\nDestape Rápido – Servicios sanitarios y arriendo de baños químicos\ndestaperapido.cl','\n',char(10)),NULL,'robcar.cl','enviado','2026-07-08T03:40:45.274Z','2026-07-08 03:40:45',NULL,replace('Estimada Cristina,\n\nJunto con saludar, adjunto cotización formal por el arriendo de baño químico con lavamanos para la obra de Los Montes 1022, Colina.\n\nResumen comercial:\n- 1 baño químico con lavamanos, arriendo mensual (contrato por 2 meses)\n- Limpieza semanal (cada 7 a 10 días) incluida sin costo\n- Despacho, instalación y retiro incluidos\n- Valor mensual: $160.000 neto · $190.400 con IVA\n- Referencia contrato total 2 meses: $380.800 con IVA\n- Facturación: factura electrónica a Ingeniería Eléctrica y Construcción ROBCAR Limitada\n- Entrega: miércoles 08 de julio, desde las 11:00 AM aprox\n- Pago: efectivo o transferencia, contra entrega\n\nEn la cotización adjunta encontrarán el detalle completo, condiciones del servicio y datos de transferencia.\n\nQuedamos atentos para coordinar la instalación. Cualquier consulta no dude en escribirnos o llamarnos al +56 9 3647 0112.\n\nSaludos cordiales,\nDestape Rápido – Servicios sanitarios y arriendo de baños químicos\ndestaperapido.cl','\n',char(10)),'2026-07-08T03:40:45.274Z','cotizacion-20260707-robcar.pdf','',1,NULL,0,NULL,NULL,NULL,'s:cotización destape rápido — arriendo de baño químico, colina|conta@robcar.cl',NULL,NULL,1,NULL,NULL,NULL);
