INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(404,'<8379318E11C5EB18C4C18837E3C6E76E@134.195.208.14>','it@datanetworkingcable.com','proyectos@destaperapido.cl','Mantenimiento Preventivo, Correctivo y Predictivo',replace('E L C\nGESTIÓN MODERNA DEL\nMANTENIMIENTO\nPREVENTIVO, CORRECTIVO Y PREDICTIVO\nCómo implementar un programa de mantenimiento preventivo, correctivo y predictivo. La digitalización y la Inteligencia Artificial en el mantenimiento.\nFECHAS: 15 Y 16 DE JULIO\nEn el horario de 7:00 pm a 10:00 pm\nDuración 6 horas o Horario GMT-5 para: Perú, Colombia, Ecuador, Panamá\n\n>PROMO 4x2 MAS INFO CLIC AQUÍ\n  \nINCLUYE: Material digital del tema a desarrollar, Asistencia Permanente del Expositor durante la capacitación, Link con la grabación de la clase y certificado digital.\nTEMARIO\no El rol de Mantenimiento en la actualidad\no Terminología de Mantenimiento según la Norma UNE-EN 13306:\no Gestión del Mantenimiento\no Estrategias de Mantenimiento.\no Objetivos del Mantenimiento\no Confiabilidad, disponibilidad y mantenibilidad\no La Digitalización y la Inteligencia Artificial en el Mantenimiento\no Implementando el Mantenimiento Preventivo\no Elementos claves para el éxito del Programa de Mantenimiento Preventivo\no Objetivos y Metas del MP proyectosdestaperapidocl\no Fase 1: Listado de equipos/Sistemas\no Fase 2: Priorizando el Mantenimiento: Criticidad de Equipos/Sistemas\no Fase 3: Listado de funciones y especificaciones de los equipos/sistemas críticos\no Fase 4: Determinación de los modos de fallo\no Fase 5: Estudio de las consecuencias de los fallos\no Fase 6: Determinación de las medidas preventivas a aplicar\no Fase 7: Planificar las medidas preventivas\no Documentación del Mantenimiento\no Información del Mantenimiento. Software CMMS (computerized maintenance management system)\no Gestión de Fallas y el Mantenimiento Correctivo\no Planificación, Programación y Ejecución del Mantenimiento\no Indicadores de Mantenimiento Preventivo / Construcción de un Balanced Scorecard, para seguimiento y mejora.\nINFORMES E INSCRIPCIONES VÍA WHATSAPP AL +51965282222\n>MAYOR INFORMACIÓN CLIC AQUÍ\nEscuela Latinoamericana de Capacitación\n\n\n\n\n\nSi no desea recibir nuestros mensajes puede pedir desuscribirse haciendo click ACA\n\n','\n',char(10)),replace('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0 Transitional//EN">\n<HTML lang=es><HEAD><TITLE>Diplomado Internacional IA NEW AI 2026 - ELC</TITLE>\n<META content="text/html; charset=iso-8859-1" http-equiv=Content-Type>\n<META name=viewport content="width=device-width, initial-scale=1.0">\n<META name=GENERATOR content="MSHTML 8.00.6001.23588"></HEAD>\n<BODY \nstyle="FONT-FAMILY: Arial, sans-serif; PADDING-BOTTOM: 0px; PADDING-TOP: 0px; PADDING-LEFT: 0px; MARGIN: 0px; PADDING-RIGHT: 0px; BACKGROUND-COLOR: #f0f4f8">\n<DIV>\n<TABLE \nstyle=''FONT-FAMILY: "Segoe UI", Arial, sans-serif; WORD-SPACING: 0px; TEXT-TRANSFORM: none; ORPHANS: 2; WIDOWS: 2; LETTER-SPACING: normal; BACKGROUND-COLOR: rgb(248,250,252); -webkit-text-stroke-width: 0px; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial'' \ncellSpacing=0 cellPadding=0 width="100%" border=0>\n  <TBODY>\n  <TR>\n    <TD \n    style="PADDING-BOTTOM: 40px; PADDING-TOP: 40px; PADDING-LEFT: 0px; PADDING-RIGHT: 0px" \n    align=center>\n      <TABLE \n      style="OVERFLOW: hidden; BACKGROUND-COLOR: rgb(255,255,255); border-radius: 20px; box-shadow: rgba(15, 23, 42, 0.08) 0px 15px 30px" \n      cellSpacing=0 cellPadding=0 width=650 border=0>\n        <TBODY>\n        <TR>\n          <TD \n          style="FONT-SIZE: 14px; F