INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(405,'911f2984-c5a9-4afb-ad8f-f36bd12b6f36','contacto@destaperapido.cl','crtvchilec@gmail.com','Cotización Destape Rápido — Arriendo de baños químicos (evento, 3 sedes)',replace('Estimados,\n\nJunto con saludar, adjunto cotización formal por arriendo de baños químicos para el evento del domingo (7 horas de duración) en Til Til, Paine y Estación Central.\n\nResumen comercial:\n- Til Til: 4 baños químicos — $125.000 neto c/u\n- Paine: 4 baños químicos — $120.000 neto c/u\n- Estación Central: 4 baños químicos — $90.000 neto c/u\n- Despacho, instalación y retiro incluidos en cada sede\n- Limpieza y disposición final al finalizar el servicio (al retiro)\n- Total evento: $1.340.000 neto · $1.594.600 con IVA\n- Facturación: pendiente de sus datos (RUT y razón social)\n\nEn la cotización adjunta encontrarán el detalle completo por sede, condiciones del servicio y observaciones.\n\nQuedamos atentos para confirmar y coordinar la instalación. Cualquier consulta no dude en escribirnos o llamarnos al +56 9 3647 0112.\n\nSaludos cordiales,\nDestape Rápido – Servicios sanitarios y arriendo de baños químicos\ndestaperapido.cl','\n',char(10)),NULL,'gmail.com','enviado','2026-07-13T14:15:29.879Z','2026-07-13 14:15:30',NULL,replace('Estimados,\n\nJunto con saludar, adjunto cotización formal por arriendo de baños químicos para el evento del domingo (7 horas de duración) en Til Til, Paine y Estación Central.\n\nResumen comercial:\n- Til Til: 4 baños químicos — $125.000 neto c/u\n- Paine: 4 baños químicos — $120.000 neto c/u\n- Estación Central: 4 baños químicos — $90.000 neto c/u\n- Despacho, instalación y retiro incluidos en cada sede\n- Limpieza y disposición final al finalizar el servicio (al retiro)\n- Total evento: $1.340.000 neto · $1.594.600 con IVA\n- Facturación: pendiente de sus datos (RUT y razón social)\n\nEn la cotización adjunta encontrarán el detalle completo por sede, condiciones del servicio y observaciones.\n\nQuedamos atentos para confirmar y coordinar la instalación. Cualquier consulta no dude en escribirnos o llamarnos al +56 9 3647 0112.\n\nSaludos cordiales,\nDestape Rápido – Servicios sanitarios y arriendo de baños químicos\ndestaperapido.cl','\n',char(10)),'2026-07-13T14:15:29.879Z','cotizacion-20260713-cdc-chile-multisede.pdf','',1,NULL,0,NULL,NULL,NULL,'s:cotización destape rápido — arriendo de baños químicos (evento, 3 sedes)|crtvchilec@gmail.com',NULL,NULL,1,NULL,NULL,NULL);
