INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(432,'23a8bdfa-2326-4766-8336-fe4a681c86c8','contacto@destaperapido.cl','gonzalo.ceruti@rpci.cl','Cotización Destape Rápido — Arriendo de baño químico',replace('Estimado/a cliente,\n\nJunto con saludar, le adjunto la cotización formal por el arriendo de baño químico para su proyecto en Huechuraba.\n\n- 2 baños químicos: $75.000 neto c/u · total $150.000, más IVA 19% (ver PDF)\n- Incluye traslado, instalación, retiro, aseo semanal (cada 7 a 10 días), papel higiénico y desodorizante.\n\nEl detalle completo está en el PDF adjunto. Para confirmar basta con responder este correo o coordinarlo por WhatsApp, y agendamos la entrega.\n\nQuedamos atentos a cualquier consulta.\n\nSaludos cordiales,\nDestape Rápido\n+56 9 3647 0112 · destaperapido.cl','\n',char(10)),NULL,'rpci.cl','enviado','2026-07-15T20:23:33.346Z','2026-07-15 20:23:33',NULL,replace('Estimado/a cliente,\n\nJunto con saludar, le adjunto la cotización formal por el arriendo de baño químico para su proyecto en Huechuraba.\n\n- 2 baños químicos: $75.000 neto c/u · total $150.000, más IVA 19% (ver PDF)\n- Incluye traslado, instalación, retiro, aseo semanal (cada 7 a 10 días), papel higiénico y desodorizante.\n\nEl detalle completo está en el PDF adjunto. Para confirmar basta con responder este correo o coordinarlo por WhatsApp, y agendamos la entrega.\n\nQuedamos atentos a cualquier consulta.\n\nSaludos cordiales,\nDestape Rápido\n+56 9 3647 0112 · destaperapido.cl','\n',char(10)),'2026-07-15T20:23:33.346Z','coti-1784147011708.pdf','',1,NULL,0,NULL,NULL,NULL,'s:cotización destape rápido — arriendo de baño químico|gonzalo.ceruti@rpci.cl',NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(433,'<CAAY1gLrVk5cvyAKLFYQ0HpFZ9=S_qvOKu+XF6A4PW7JpgPtuOg@mail.gmail.com>','benja@nebulasound.cl','contacto@destaperapido.cl','Re: Cotización Destape Rápido — Arriendo de baño químico',replace('Acuso recibo,\n\nLo revisamos con el equipo y volvemos a ti,\n\nAgradecido desde ya.\n\nB.\n\nOn Wed, Jul 15, 2026 at 12:21 PM Destape Rápido <contacto@destaperapido.cl>\nwrote:\n\n> Estimado/a cliente,\n>\n> Junto con saludar, le adjunto la cotización formal por el arriendo de baño\n> químico para su proyecto en Huechuraba.\n>\n> - 3 baños químicos: $255.000 neto, más flete y IVA 19% (total en el PDF)\n> - Incluye traslado, instalación, retiro, aseo semanal (cada 7 a 10 días),\n> papel higiénico y desodorizante.\n>\n> El detalle completo está en el PDF adjunto. Para confirmar basta con\n> responder este correo o coordinarlo por WhatsApp, y agendamos la entrega.\n>\n> Quedamos atentos a cualquier consulta.\n>\n> Saludos cordiales,\n> Destape Rápido\n> +56 9 3647 0112 · destaperapido.cl\n\n','\n',char(10)),replace('<div dir="ltr">Acuso recibo,<br><br>Lo revisamos con el equipo y volvemos a ti,<br><br>Agradecido desde ya.<br><br>B.</div><br><div class="gmail_quote gmail_quote_container"><div dir="ltr" class="gmail_attr">On Wed, Jul 15, 2026 at 12:21 PM Destape Rápido &lt;<a href="mailto:contacto@destaperapido.cl">contacto@destaperapido.cl</a>&gt; wrote:<br></div><blockquote class="gmail_quote" style="margin:0px 0px 0px 0.8ex;border-left:1px solid rgb(204,204,204);padding-left:1ex">Estimado/a cliente,<br>\n<br>\nJunto con saludar, le adjunto la cotización formal por el arriendo de baño químico para su proyecto en Huechuraba.<br>\n<br>\n- 3 baños químicos: $255.000 neto, más flete y IVA 19% (total en el PDF)<br>\n- Incluye traslado, instalación, retiro, aseo semanal (cada 7 a 10 días), papel higiénico y desodorizante.<br>\n<br>\nEl detalle completo está en el PDF adjunto. Para confirmar basta con responder este correo o coordinarlo por WhatsApp, y agendamos la entrega.<br>\n<br>\nQuedamos atentos a cualquier consulta.<br>\n<br>\nSaludos cordiales,<br>\nDestape Rápido<br>\n+56 9 3647 0112 · <a href="http://destaperapido.cl" rel="noreferrer" target="_blank">destaperapido.cl</a></blockquote></div>\n\n','\n',char(10)),'destaperapido.cl','archivado','2026-07-15T21:44:02.000Z','2026-07-15 21:44:16',replace('Estimado Benja, muchas gracias por acusar recibo.\n\nQuedamos atentos a sus comentarios cuando lo revisen con el equipo. Si necesitan ajustar la cantidad de baños, las fechas o tienen cualquier duda sobre la cotización, con gusto lo vemos.\n\nSaludos cordiales,\nDestape Rápido\n+56 9 3647 0112 · destaperapido.cl','\n',char(10)),NULL,NULL,NULL,NULL,1,NULL,0,'alta',NULL,'5f530715592d202a71dc09c4a6c345ddf2b1c50a95df67b0af6fedb36efe9fd9','s:cotización destape rápido — arriendo de baño químico|benja@nebulasound.cl','<0100019f6695b55e-141aaff2-ad4e-4554-90f2-bfc6f968e2d0-000000@email.amazonses.com>','<0100019f6695b55e-141aaff2-ad4e-4554-90f2-bfc6f968e2d0-000000@email.amazonses.com>',1,NULL,NULL,'borrador');
INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(434,'<B54F06EFA276588B57521BA5D12E059A@134.195.208.17>','it@thebestphonesupport.com','contacto@destaperapido.cl','Claude AI Pro - Contruye tu Sistema de Trabajo con IA',replace('E L C\nCLAUDE AI PRO:\nCONSTRUYE TU SISTEMA\nDE TRABAJO CON IA\n\nUsa Claude para organizar información, crear herramientas y automatizar tareas profesionales.\nDomina las funciones más avanzadas de Claude IA:\nProyectos, Artefactos, Skills, Claude Code, MCP y automatización de proyectos.\n\nBeneficios:\nTransforma la manera en que trabajas utilizando IA para resolver tareas complejas, organizar proyectos y crear soluciones en minutos.\nFECHAS: 17 Y 20 DE JULIO\nEn el horario de 7:00 pm a 10:00 pm\nDuración 6 horas o Horario GMT-5 para: Perú, Colombia, Ecuador, Panamá\n\n?? PROMO 4x2 MAS INFO CLIC AQUÍ\n  \nINCLUYE: Material digital del tema a desarrollar, Asistencia Permanente del Expositor durante la capacitación, Link con la grabación de la clase y certificado digital.\nCONTENIDO\no Qué es Claude AI\no Modelos de Claude AI\no Capacidades y limitations\no Diseño de prompts personalizados para Claude\no Área de Proyectos para trabajo organizado\no Artefactos: Crear herramientas y aplicaciones\no Función de pensamiento profundo\no Skills: automatizar tareas contactodestaperapidocl\no MPC: Conectores con herramientas digitales\no Uso de Claude en Office 365\no Claude Desktop: Cowork - Claude Code\nINFORMES E INSCRIPCIONES VÍA WHATSAPP AL +51998236916\n?? MAYOR INFORMACIÓN CLIC AQUÍ\nEscuela Latinoamericana de Capacitación\n\n\n\n\n\nSi no desea recibir nuestros mensajes puede pedir