INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(477,'<E71D55EA75A18F2CF0F5BC0327863E9A@74.48.149.9>','it@thereisnobadnews.com','proyectos@destaperapido.cl','Project Management con IA y PowerBi',replace('E L C\nPROJECT MANAGEMENT\nCON POWER BI E\nINTELIGENCIA ARTIFICIAL\nFECHAS: 27 Y 30 DE JULIO\nEn el horario de 7:00 pm a 10:00 pm\nDuración 6 horas o Horario GMT-5 para: Perú, Colombia, Ecuador, Panamá\n\n?? PROMO ESPECIAL MAS INFO CLIC AQUÍ\n  \nINCLUYE: Material digital del tema a desarrollar, Asistencia Permanente del Expositor durante la capacitación, Link con la grabación de la clase y certificado digital.\nCONTENIDO\nMÓDULO 1: DISEÑO DEL SISTEMA DE CONTROL DEL PROYECTO Y CONSTRUCCIÓN DEL DASHBOARD BASE\no Del plan al dato: estructura de control del proyecto con EDT/WBS, cronograma, línea base, costos, responsables, hitos y riesgos\no Arquitectura de datos en Power BI: carga con Power Query, calidad de datos y modelo estrella para proyectos\no KPIs esenciales de desempeño: avance planificado y real, PV, EV, AC, SV, CV, SPI, CPI y desviaciones proyectosdestaperapidocl\no Visualización ejecutiva: tarjetas, curva S, Gantt, semáforos RAG, hitos y análisis por fase, responsable y paquete de trabajo\no Construcción guiada de un dashboard de control de proyecto: línea base vs. avance real, costos y alertas tempranas\nMÓDULO 2: CONTROL PREDICTIVO Y TOMA DE DECISIONES CON POWER BI E INTELIGENCIA ARTIFICIAL\no Medidas DAX para pronóstico y cierre: EAC, ETC, VAC, TCPI, cumplimiento de hitos y exposición al riesgo\no IA aplicada al diagnóstico: identificación de desviaciones, causas probables, riesgos emergentes y preguntas de control\no Escenarios y decisiones: priorización de acciones, reprogramación, reasignación de recursos y recuperación del proyecto\no Storytelling ejecutivo asistido por IA: reporte de estado, resumen para comité, plan de acción y controles de calidad, privacidad y trazabilidad\no Proyecto integrador: dashboard ejecutivo con pronóstico, análisis asistido por IA y reporte de estado con decisiones recomendadas\nINFORMES E INSCRIPCIONES VÍA WHATSAPP AL +51959117612\n?? MAYOR INFORMACIÓN CLIC AQUÍ\nEscuela Latinoamericana de Capacitación\n\n\n\n\n\nSi no desea recibir nuestros mensajes puede pedir desuscribirse haciendo click ACA\n\n','\n',char(10)),replace('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0 Transitional//EN">\n<HTML><HEAD>\n<META content="text/html; charset=iso-8859-1" http-equiv=Content-Type>\n<META name=GENERATOR content="MSHTML 10.00.9200.16897"></HEAD>\n<BODY bottomMargin=5 bgColor=#ffffff leftMargin=5 topMargin=5 rightMargin=5>\n<DIV>\n<DIV><FONT size=1>\n<DIV \nstyle=''FONT-SIZE: medium; FONT-FAMILY: "Times New Roman"; WHITE-SPACE: normal; WORD-SPACING: 0px; TEXT-TRANSFORM: none; FONT-WEIGHT: 400; COLOR: rgb(0,0,0); FONT-STYLE: normal; ORPHANS: 2; WIDOWS: 2; LETTER-SPACING: normal; TEXT-INDENT: 0px; -webkit-text-stroke-width: 0px; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-variant-ligatures: normal; font-variant-caps: normal'' \nalign=center>\n<DIV \nstyle=''FONT-SIZE: medium; FONT-FAMILY: "Times New Roman"; WHITE-SPACE: normal; WORD-SPACING: 0px; TEXT-TRANSFORM: none; FONT-WEIGHT: 400; COLOR: rgb(0,0,0); FONT-STYLE: normal; ORPHANS: 2; WIDOWS: 2; LETTER-SPACING: normal; TEXT-INDENT: 0px; -webkit-text-stroke-width: 0px; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-variant-ligatures: normal; font-variant-caps: normal'' \nalign=center><FONT size=1>\n<DIV \nstyle=''FONT-SIZE: medium; FONT-FAMILY: "Times New Roman"; WHI