INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(500,'29bf48e9-9b6b-4f33-a559-eed066f99cdc','contacto@destaperapido.cl','cbenavides@prymave.cl','Cotización Destape Rápido — Arriendo de baño químico',replace('Estimado/a cecilia benavides,\n\nJunto con saludar, le adjunto la cotización formal por el arriendo de baño químico para su proyecto en Renca.\n\n- un baño químico: $160.000 neto (total con IVA: $190.400)\n- Incluye traslado, instalación, retiro, aseo semanal (cada 7 a 10 días), papel higiénico y desodorizante.\n\nEl detalle completo está en el PDF adjunto. Para confirmar basta con responder este correo o coordinarlo por WhatsApp, y agendamos la entrega.\n\nQuedamos atentos a cualquier consulta.\n\nSaludos cordiales,\nDestape Rápido\n+56 9 3647 0112 · destaperapido.cl','\n',char(10)),NULL,'prymave.cl','enviado','2026-07-29T17:54:12.594Z','2026-07-29 17:54:13',NULL,replace('Estimado/a cecilia benavides,\n\nJunto con saludar, le adjunto la cotización formal por el arriendo de baño químico para su proyecto en Renca.\n\n- un baño químico: $160.000 neto (total con IVA: $190.400)\n- Incluye traslado, instalación, retiro, aseo semanal (cada 7 a 10 días), papel higiénico y desodorizante.\n\nEl detalle completo está en el PDF adjunto. Para confirmar basta con responder este correo o coordinarlo por WhatsApp, y agendamos la entrega.\n\nQuedamos atentos a cualquier consulta.\n\nSaludos cordiales,\nDestape Rápido\n+56 9 3647 0112 · destaperapido.cl','\n',char(10)),'2026-07-29T17:54:12.594Z','coti-c5dc5526340ea5d3.pdf','',1,NULL,0,NULL,NULL,NULL,'s:cotización destape rápido — arriendo de baño químico|cbenavides@