INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(501,'<CAA74o=NHHp8gRHz8y1CoosUundKEFbnYjHjVQ1BZUC+dyUg6Aw@mail.gmail.com>','smiranda@lumicor.cl','contacto@destaperapido.cl','Producto químico para baños portátiles',replace('Estimados,\n\nLe escribo para presentarle los desodorantes para baños portátiles\nQuickScents BIO de 60 gramos de la marca Satellite, los cuales ofrecen una\nprotección fuerte y duradera para sus instalaciones.\n\nEstos sobres en polvo totalmente naturales combinan el control de olores\ncon el poder de limpieza, descomponiendo los residuos en las paredes del\ntanque y tuberías para evitar acumulaciones y malos olores. Además, sus\ningredientes activos benefician a las plantas de tratamiento de aguas\nresiduales, facilitando su posterior eliminación.\n\nQuedo a su disposición para brindarle más información o resolver cualquier\nduda.\n\nAtentamente,\n\n','\n',char(10)),replace('<div dir="ltr"><div><div><div>Estimados,</div><div><br></div><div>Le escribo para presentarle los desodorantes para baños portátiles QuickScents BIO de 60 gramos de la marca Satellite, los cuales ofrecen una protección fuerte y duradera para sus instalaciones.</div><div><br></div><div>Estos sobres en polvo totalmente naturales combinan el control de olores con el poder de limpieza, descomponiendo los residuos en las paredes del tanque y tuberías para evitar acumulaciones y malos olores. Además, sus ingredientes activos benefician a las plantas de tratamiento de aguas residuales, facilitando su posterior eliminación.</div><div><br></div><div>Quedo a su disposición para brindarle más información o resolver cualquier duda.</div><div><br></div><div>Atentamente,</div></div></div><div><div dir="ltr" class="gmail_signature" data-smartmail="gmail_signature"><div dir="ltr"><img width="420" height="233" src="https://ci3.googleusercontent.com/mail-sig/AIorK4yjweoCng0L8uPhz6EVzwG7Oa9rgt1Cm79eLdccvryUhmQ5GWIB3iHB4h-a2XlnBVhYLliU4lgBsJUF"></div></div></div></div>\n\n','\n',char(10)),'destaperapido.cl','nuevo','2026-07-29T18:33:31.000Z','2026-07-29 18:33:46',NULL,NULL,NULL,NULL,NULL,1,NULL,0,NULL,NULL,'ee362eb1d9ec0598fe91b60da3980e0ae77565801b046ca1f4308931af95721b','s:producto químico para baños portátiles|smiranda@lumicor.cl',NULL,NULL,1,NULL,NULL,NULL);
