INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(535,'b4744466-d3f7-434d-8f1e-20f2b304714e','contacto@destaperapido.cl','Lzapata@audaxitaliano.cl','Cotización Destape Rápido — Arriendo de baño químico',replace('Estimado/a cliente,\n\nJunto con saludar, le adjunto la cotización formal por el arriendo de baño químico para su proyecto en Puente Alto.\n\n- un baño químico: $160.000 neto (total con IVA: $190.400)\n- Incluye traslado, instalación, retiro, aseo semanal (cada 7 a 10 días), papel higiénico y desodorizante.\n\nEl detalle completo está en el PDF adjunto. Para confirmar basta con responder este correo o coordinarlo por WhatsApp, y agendamos la entrega.\n\nQuedamos atentos a cualquier consulta.\n\nSaludos cordiales,\nDestape Rápido\n+56 9 3647 0112 · destaperapido.cl','\n',char(10)),NULL,'audaxitaliano.cl','enviado','2026-08-04T15:59:28.936Z','2026-08-04 15:59:29',NULL,replace('Estimado/a cliente,\n\nJunto con saludar, le adjunto la cotización formal por el arriendo de baño químico para su proyecto en Puente Alto.\n\n- un baño químico: $160.000 neto (total con IVA: $190.400)\n- Incluye traslado, instalación, retiro, aseo semanal (cada 7 a 10 días), papel higiénico y desodorizante.\n\nEl detalle completo está en el PDF adjunto. Para confirmar basta con responder este correo o coordinarlo por WhatsApp, y agendamos la entrega.\n\nQuedamos atentos a cualquier consulta.\n\nSaludos cordiales,\nDestape Rápido\n+56 9 3647 0112 · destaperapido.cl','\n',char(10)),'2026-08-04T15:59:28.936Z','coti-b02e7813ac76add2.pdf','',1,NULL,0,NULL,NULL,NULL,'s:cotización destape rápido — arriendo de baño químico|lzapata@audaxitaliano.cl',NULL,NULL,1,NULL,NULL,NULL);
