INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(574,'a07d0f45-c985-4508-9dcc-d0d4ce7ab2b5','contacto@destaperapido.cl','francisco777.urrutia@gmail.com','Cotización Destape Rápido — Arriendo de baño químico',replace('Estimado/a Francisco,\n\nJunto con saludar, le adjunto la cotización formal por el arriendo de baño químico para su proyecto en Las Condes.\n\n- un baño químico: $160.000 neto (total con IVA: $190.400)\n- Incluye traslado, instalación, retiro, aseo semanal (cada 7 a 10 días), papel higiénico y desodorizante.\n\nEl detalle completo está en el PDF adjunto. Para confirmar basta con responder este correo o coordinarlo por WhatsApp, y agendamos la entrega.\n\nQuedamos atentos a cualquier consulta.\n\nSaludos cordiales,\nDestape Rápido\n+56 9 3647 0112 · destaperapido.cl','\n',char(10)),NULL,'gmail.com','enviado','2026-08-08T18:22:56.351Z','2026-08-08 18:22:56',NULL,replace('Estimado/a Francisco,\n\nJunto con saludar, le adjunto la cotización formal por el arriendo de baño químico para su proyecto en Las Condes.\n\n- un baño químico: $160.000 neto (total con IVA: $190.400)\n- Incluye traslado, instalación, retiro, aseo semanal (cada 7 a 10 días), papel higiénico y desodorizante.\n\nEl detalle completo está en el PDF adjunto. Para confirmar basta con responder este correo o coordinarlo por WhatsApp, y agendamos la entrega.\n\nQuedamos atentos a cualquier consulta.\n\nSaludos cordiales,\nDestape Rápido\n+56 9 3647 0112 · destaperapido.cl','\n',char(10)),'2026-08-08T18:22:56.351Z','coti-5adb95cd228ecbef.pdf','',1,NULL,0,NULL,NULL,NULL,'s:cotización destape rápido — arriendo de baño químico|francisco777.urrutia@gmail.com',NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(575,'<02F8B33EC91D33D00C0940FE5AC23EE0@134.195.208.17>','it@vladns.com','proyectos@destaperapido.cl','DipIomado en Marketing aplicando IA - Gestión Comercial, Webs, Análisis Datos, Mkt de Contenido..',replace('  \nE L C\nDIPLOMADO EN\nMARKETING DIGITAL CON INTELIGENCIA ARTIFICIAL \n- AI MARKETING STRATEGY\n¡Cómo convertir la Inteligencia Artificial en el copiloto estratégico para marketing digital y ventas para escalar tu negocio!\nFECHAS DE INICIO: 12 DE AGOSTO\nEn el horario de 7:00 pm a 10:00 pm\nDuración 33 horas o Lunes, Miércoles y Viernes o Horario GMT-5 para: Perú, Colombia, Ecuador, Panamá \nINCLUYE: Material digital del tema a desarrollar, Asistencia Permanente del Expositor durante la capacitación, Link con la grabación de la clase y certificado digital.\nLa inteligencia artificial está transformando la forma en que las empresas planifican su marketing, atraen clientes y optimizan sus resultados comerciales. Este diplomado te permitirá utilizar la IA como apoyo estratégico en marketing digital para investigar mercados con mayor precisión, estructurar planes, crear contenido de forma eficiente y optimizar campañas basándose en datos reales.\n> PROMO DISPONIBLE CLIC AQUÍ\nCONTENIDO\nMódulo 1: Fundamentos de Inteligencia Artificial para Marketing Digital\nIntroducción a la Inteligencia Artificial\no Qué es la Inteligencia Artificial.\no Qué es la IA generativa.\no Tipos de IA aplicadas al marketing: texto, imagen, video y audio.\no Cómo la IA transforma la planificación, creación y optimización del marketing digital.\nLLMs aplicados al marketing\no Qué es un LLM.\no Cómo funcionan los modelos de lenguaje.\no Diferencias entre ChatGPT, Gemini, Claude.\no Cuándo usar cada IA según el tipo de tarea.\nPrompt Engineering\no Qué es prompting.\no Estructura profesional de prompts.\no Tipos de prompts aplicados a marketing.\no Prompts para investigación, estrategia, contenidos, campañas y análisis.\nIntroducción a agentes IA\no Qué es un agente IA.\no Diferencia entre prompts y agentes.\no Uso de proyectos en ChatGPT y Claude.\no Cómo organizar flujos de trabajo con IA.\n\nMódulo 2: Investigación de Mercado y Cliente Ideal con IA\nInvestigación estratégica con IA\no Cómo investigar mercados con LLMs.\no Benchmark competitivo con IA.\no Identificación de oportunidades de negocio.\no Análisis de tendencias con IA.\no Detección de problemas, necesidades y comportamientos del mercado.\nConstrucción del cliente ideal\no Buyer persona con IA.\no Mapa de dolores y necesidades.\no Mapa de motivaciones de compra.\no Objeciones frecuentes del cliente.\no Factores que influyen en la decisión de compra.\nSegmentación estratégica\no Segmentación B2C.\no Segmentación B2B.\no Segmentación psicográfica.\no Segmentación comportamental.\no Priorización de segmentos con mayor potencial comercial.\nTaller práctico\no Creación del perfil de cliente ideal con IA.\no Desarrollo de un análisis base de mercado y competencia.\n\nMódulo 3: Propuesta de Valor, Posicionamiento y Plan Estratégico de Marketing\nConstrucción de la propuesta de valor\no Identificación del problema principal.\no Definición de la promesa de valor.\no Diferenciación competitiva.\no Resultados esperados del cliente.\no Argumentos clave para comunicar valor.\nPosicionamiento estratégico\no Desarrollo del mensaje central.\no Ángulos de marketing.\no Storyselling con IA.\no Adaptación del mensaje según público, canal y etapa del funnel.\nConstrucción del plan estratégico de marketing\no Definición de objetivos comerciales.\no KPIs estratégicos.\no Selección de canales digitales.\no Roadmap estratégico de marketing de 90 días.\no Priorización de acciones según impacto y facilidad de ejecución.\nTaller práctico\no Desarrollo de la propuesta de valor.\no Construcción del plan estratégico base.\n\nMódulo 4: Sistema Digital de Captación y Conversión con IA\nArquitectura del funnel de ventas\no Estructura del funnel digital.\no Atracción.\no Captura.\no Nutrición.\no Conversión.\no Fidelización.\no Relación entre marketing, ventas y experiencia del cliente.\nCustomer journey estratégico\no Puntos de contacto digitales.\no Diseño de la experiencia del cliente.\no Mensajes clave por etapa del recorrido.\no Identificación de fricciones y oportunidades de mejora.\nLead magnets con IA\no Tipos de lead magnets.\no Validación de ideas con IA.\no Creación de lead magnets orientados a conversión.\no Alineación del lead magnet con el cliente ideal y la propuesta de valor.\nLanding pages orientadas a conversión\no Elementos de una landing page efectiva.\no Estructura estratégica de una página de captura..\no Copywriting para landing pages con IA.\no Optimización de mensajes, beneficios y llamados a la acción.\nTaller práctico\no Diseño del funnel completo.\no Creación de la estructura de una landing page.\no Desarrollo de una propuesta de lead magnet.\n\nMódulo 5: Email Marketing, WhatsApp y Seguimiento Comercial con IA\nEmail marketing estratégico\no Rol del email dentro del funnel de ventas.\no Tipos de emails: captación, nutrición, conversión y fidelización.\no Diferencia entre campañas puntuales y secuencias de seguimiento.\no Buenas prácticas para mejorar apertura, lectura y respuesta.\no Uso de IA para crear estructuras y versiones de emails.\nSecuencias de emails con IA\no Estructura de una secuencia de emails.\no Secuencias clave: bienvenida, nutrición, venta y reactivación.\no Personalización de mensajes según segmento y etapa del prospecto.\no Optimización de asuntos, preheaders y llamados a la acción.\no Adaptación del tono según marca, público y objetivo comercial.\nSeguimiento comercial por WhatsApp\no Rol de WhatsApp dentro del proceso de ventas.\no Momentos clave para contactar a un prospecto.\no Mensajes de primer contacto, seguimiento, reactivación y cierre.\no Uso de IA para crear mensajes comerciales más claros y personalizados.\no Buenas prácticas para evitar mensajes invasivos o repetitivos.\nPipeline comercial en WhatsApp\no Qué es un pipeline comercial y por qué ayuda a ordenar el seguimiento.\no Etapas básicas: nuevo lead, contactado, interesado, propuesta enviada, seguimiento, cierre ganado y cierre perdido.\no Clasificación de leads según interés, urgencia y oportunidad comercial.\no Priorización de prospectos y próximos pasos.\no Indicadores básicos: leads activos, tasa de respuesta, propuestas enviadas y cierres.\nTaller práctico\no Creación de una secuencia básica de emails.\no Desarrollo de mensajes de seguimiento por WhatsApp.\no Diseño de un pipeline comercial simple.\no Creación de plantillas para objeciones frecuentes.\n\nMódulo 6: Estrategia de Contenidos, SEO y Redes Sociales con IA\n1. Estrategia de contenidos orientada a ventas\no Contenido según el funnel: TOFU, MOFU y BOFU.\no Pilares de contenido alineados al cliente ideal y propuesta de valor.\no Diferencia entre contenido educativo, de autoridad, confianza y conversión.\no Relación entre contenido, marca y generación de demanda.\n2. Creación de contenido con IA para redes sociales\no Generación de ideas de contenido con IA.\no Creación de posts para redes sociales.\no Adaptación de mensajes por canal y formato.\no Reutilización de contenidos con IA.\n3. SEO práctico con IA\no Ideación de temas SEO con IA.\no Estructura básica de artículos optimizados.\no Optimización de títulos, subtítulos y descripciones.\no Creación de contenidos para atraer tráfico calificado.\n4. Planificación de contenidos\no Calendario editorial mensual.\no Priorización de contenidos según objetivos comerciales.\no Organización simple del flujo de producción de contenido.\nTaller práctico\no Desarrollo de un calendario mensual de contenidos.\no Creación de piezas base para redes sociales.\no Estructura de un artículo SEO.\no Adaptación de una pieza de contenido a distintos formatos.\n\nMódulo 7: Creatividad Visual, Imágenes y Video Marketing con IA\n1. Creatividad visual aplicada al marketing\no Traducción de mensajes comerciales en ideas visuales.\no Desarrollo de conceptos creativos para contenidos y campañas.\no Relación entre mensaje, formato y objetivo comercial.\n2. Creación de imágenes con IA\no Generación de imágenes con ChatGPT o Gemini.\no Creación de imágenes para redes sociales.\no Variantes visuales simples para pruebas creativas.\n3. Video marketing con IA\no Tipos de videos según objetivo: educativo, autoridad, publicitario y conversión.\no Creación de guiones cortos para video con IA.\no Adaptación de una idea visual a formato video.\n4. Producción audiovisual básica con IA\no Flujo simple de producción: idea, guion, imagen/video y publicación.\nTaller práctico\no Desarrollo de un concepto visual.\no Creación de una imagen base con IA.\no Creación de un guion corto.\no Producción de una pieza audiovisual simple con IA.\n\nMódulo 8: Publicidad Digital y Analítica con IA\nEstrategia de campañas digitales\no Arquitectura de campañas digitales.\no Definición de audiencias.\no Ángulos publicitarios.\no Selección de plataformas según objetivo comercial.\no Meta Ads.\no Linkedin Ads.\no Google Ads.\nCopywriting publicitario con IA\no Hooks publicitarios.\no Beneficios vs características.\no Llamados a la acción efectivos.\no Creación de variaciones de anuncios con IA.\no Adaptación del copy según plataforma y etapa del funnel.\nCreativos publicitarios con IA\no Creación de conceptos visuales.\no Generación de imágenes publicitarias.\no Variantes creativas.\no Relación entre mensaje, formato y objetivo de campaña.\nTesting y optimización\no Variaciones de anuncios.\no Introducción al testing A/B.\no Optimización de campañas.\nAnalítica de marketing con IA\no Marketing basado en datos.\no KPIs clave de marketing: CAC, ROAS, CTR, Conversion Rate y CPL.\no Interpretación de resultados con IA.\nTaller práctico final\no Desarrollo de una ficha estratégica de campaña.\no Análisis de métricas y oportunidades de optimización.\n\nMódulo 9: Análisis de Datos y Estadística Aplicada a Marketing y Ventas con Inteligencia Artificial (DIEGO MIRANDA - CHILE)\nA) Fundamentos de Datos en Marketing y Ventas\no Introducción al análisis de datos en negocios\no Tipos de datos en marketing:\no Datos de clientes\no Datos de ventas\no Datos de comportamiento\no Principales indicadores (KPIs):\no Ventas totales\no Frecuencia de compra\no Tasa de conversión\no Flujo de valor:\no Datos - Información - Decisiones\nActividad práctica:\no Análisis inicial de un dataset de ventas:\no Identificación de variables\no Cálculo de ventas totales\no Identificación del producto más vendido\nB) Análisis Exploratorio de Datos (EDA) aplicado a Negocio\no Estadística descriptiva:\no Media\no Mediana\no Desviación estándar\no Análisis por segmentación:\no Clientes por edad\no Clientes por región\no Clientes por frecuencia de compra\no Visualización de datos:\no Ventas por fecha\no Ventas por producto\no Distribución de clientes\nHerramientas:\no Python (Pandas, Matplotlib)\no Actividad práctica:\no Identificación de:\no Clientes frecuentes vs ocasionales\no Productos más rentables\no Días de mayor venta\no Generación de gráficos simples\nC) Inteligencia Artificial aplicada a Marketing y Ventas\n1. Segmentación de clientes (Clustering)\no Introducción a K-Means\no Agrupación automática de clientes\no Interpretación de segmentos:\no Clientes premium\no Clientes ocasionales\no Clientes sensibles al precio\n2. Predicción de ventas\no Introducción a modelos predictivos\no Variables relevantes:\no Tiempo (fecha)\no Promociones\no Historial de ventas\no Modelos simples:\no Regresión\no Árboles de decisión\n3. Sistemas de recomendación\no Concepto:\no "Clientes similares compran productos similares"\no Aplicación básica en ventas\nActividad práctica:\no Segmentación de clientes mediante clustering\no Construcción de un modelo simple de predicción\no Interpretación de resultados\nD) Toma de Decisiones Basadas en Datos\no Transformación de análisis en estrategias:\no Segmentación de campañas\no Optimización de inventario\no Identificación de oportunidades de venta\no Casos de uso:\no Aumento de ventas\no Reducción de costos\no Mejora de conversión\nHerramientas Utilizadas en el curso\no Python (Google Colab recomendado)\no Librerías:\no pandas\no numpy\no matplotlib\no scikit-learn\n\nMódulo Extra: Vibe Coding para Landing Pages, Webs, E-commerce y CRM con IA\n1. Introducción al Vibe Coding y criterios de implementación\no Qué es Vibe Coding.\no Cómo crear soluciones digitales usando instrucciones en lenguaje natural.\no Casos de uso en marketing, ventas y captación de clientes.\no Herramientas del módulo: Claude Code, Codex y Antigravity.\no Cuándo usar código directo y cuándo usar WordPress.\no Criterios de decisión: velocidad, flexibilidad, mantenimiento, escalabilidad y nivel de personalización.\n2. Creación de Landing Pages con IA\no Estructura de una landing page orientada a conversión.\no Generación de copywriting con IA.\no Creación de formularios y captación de contactos.\no Desarrollo asistido con Claude Code, Codex y Antigravity.\no Optimización básica para campañas y funnels de venta.\n3. Creación de una página web corporativa con IA\no Estructura web: inicio, servicios, nosotros, contacto y CTA.\no Arquitectura de navegación y experiencia del usuario.\no Generación de textos, secciones y contenido can IA.\no Adaptación del proyecto a código directo o WordPress.\n4. Creación de una tienda online con IA\no Estructura comercial de una tienda online.\no Catálogo, categorías, fichas de producto y carrito.\no Generación de descripciones y contenido de producto con IA.\no Implementación con WordPress o código directo según el caso.\n5. Integración de chat web inteligente, CRM e IA\no Diseño del flujo conversacional. proyectosdestaperapidocl\no Creación de una base de conocimiento para atención automática.\no Integración del chat en landing pages, webs y tiendas online.\no Captura automática de leads desde formularios y chats.\no Registro y organización de contactos en CRM.\no Clasificación de prospectos y seguimiento comercial con IA.\nInscripciones abiertas vía WhatsApp al +51959117612\n>MÁS INFORMACIÓN CLIC AQUÍ\nELC - Escuela Latinoamericana de Capacitación\nLiderando la transformación\n\n\n\nSi no desea recibir nuestros mensajes puede pedir desuscribirse haciendo click ACA\n\n','\n',char(10)),replace('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0 Transitional//EN">\n<HTML><HEAD>\n<META content="text/html; charset=iso-8859-1" http-equiv=Content-Type>\n<META name=GENERATOR content="MSHTML 11.00.9600.17105">\n<STYLE></STYLE>\n</HEAD>\n<BODY bgColor=#ffffff>\n<DIV>\n<DIV>\n<DIV><FONT size=1>\n<DIV>&nbsp; \n<DIV>\n<DIV>\n<TABLE \nstyle=''FONT-FAMILY: "Segoe UI", Arial, sans-serif; WORD-SPACING: 0px; TEXT-TRANSFORM: none; ORPHANS: 2; WIDOWS: 2; LETTER-SPACING: normal; BACKGROUND-COLOR: rgb(248,250,252); -webkit-text-stroke-width: 0px; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial'' \ncellSpacing=0 cellPadding=0 width="100%" border=0>\n  <TBODY>\n  <TR>\n    <TD \n    style="PADDING-BOTTOM: 40px; PADDING-TOP: 40px; PADDING-LEFT: 0px; PADDING-RIGHT: 0px" \n    align=center>\n      <TABLE \n      style="OVERFLOW: hidden; BACKGROUND-COLOR: rgb(255,255,255); border-radius: 20px; box-shadow: 0px 15px 30px rgba(0,0,0,0.15)" \n      cellSpacing=0 cellPadding=0 width=650 border=0>\n        <TBODY>\n        <TR>\n          <TD \n          style="FONT-SIZE: 14px; FONT-WEIGHT: bold; COLOR: rgb(255,255,255); PADDING-BOTTOM: 18px; PADDING-TOP: 18px; PADDING-LEFT: 18px; LETTER-SPACING: 4px; PADDING-RIGHT: 18px; BACKGROUND-COLOR: rgb(15,23,42)" \n          align=center>E L C</TD></TR>\n        <TR>\n          <TD \n          style="BORDER-BOTTOM: rgb(37,99,235) 4px solid; PADDING-BOTTOM: 65px; PADDING-TOP: 65px; PADDING-LEFT: 40px; PADDING-RIGHT: 40px; BACKGROUND-COLOR: rgb(30,58,138)" \n          align=center>\n            <H1 \n            style="FONT-SIZE: 28px; TEXT-TRANSFORM: uppercase; FONT-WEIGHT: 900; COLOR: rgb(255,255,255); MARGIN: 0px; LINE-HEIGHT: 1.2"><SPAN \n            lang=ES-PE>\n            <P>DIPLOMADO EN</P></SPAN><SPAN \n            style="FONT-SIZE: 21pt; COLOR: rgb(96,165,250)"><SPAN \n            lang=ES-PE>MARKETING DIGITAL CON INTELIGENCIA \n            ARTIFICIAL</SPAN></SPAN>&nbsp;<BR><SPAN lang=ES-PE>- AI MARKETING \n            STRATEGY</SPAN></H1>\n            <H2 \n            style="FONT-SIZE: 16px; FONT-WEIGHT: 700; COLOR: rgb(255,255,255); MARGIN: 20px 0px 25px; LETTER-SPACING: 0px; LINE-HEIGHT: 1.4"><SPAN \n            lang=ES-PE>\n            <P>¡Cómo convertir la Inteligencia Artificial en el copiloto \n            estratégico para marketing digital y ventas para escalar tu \n            negocio!</P></SPAN></H2>\n            <DIV \n            style="FONT-SIZE: 16px; MAX-WIDTH: 540px; COLOR: rgb(219,234,254); LINE-HEIGHT: 1.5"><STRONG \n            style="TEXT-TRANSFORM: uppercase; COLOR: rgb(255,255,255)">FECHAS DE \n            INICIO: 12 DE<SPAN>&nbsp;</SPAN></STRONG><STRONG><SPAN \n            style="TEXT-TRANSFORM: uppercase; COLOR: rgb(255,255,255)">AGOSTO</SPAN></STRONG><BR><SPAN>En \n            el horario de 7:00 pm a 10:00 pm</SPAN><BR><SPAN \n            style="FONT-SIZE: 14px; FONT-WEIGHT: 600; COLOR: rgb(96,165,250)">Duración \n            33 horas o Lunes, Miércoles y Viernes o Horario GMT-5 para: Perú, \n            Colombia, Ecuador, Panamá</SPAN> \n            <P \n            style="FONT-SIZE: 11px; TEXT-TRANSFORM: uppercase; COLOR: rgb(148,163,184); MARGIN: 15px 0px 0px; LINE-HEIGHT: 1.4"><STRONG>INCLUYE:</STRONG><SPAN>&nbsp;</SPAN>Material \n            digital del tema a desarrollar, Asistencia Permanente del Expositor \n            durante la capacitación, Link con la grabación de la clase y \n            certificado digital.</P></DIV></TD></TR>\n        <TR>\n          <TD \n          style="PADDING-BOTTOM: 10px; TEXT-ALIGN: center; PADDING-TOP: 45px; PADDING-LEFT: 50px; PADDING-RIGHT: 50px; BACKGROUND-COLOR: rgb(255,255,255)">\n            <P \n            style="FONT-SIZE: 16px; COLOR: rgb(51,65,85); MARGIN: 0px; LINE-HEIGHT: 1.7">La \n            inteligencia artificial está transformando la forma en que las \n            empresas planifican su marketing, atraen clientes y optimizan sus \n            resultados comerciales. Este diplomado te permitirá utilizar la IA \n            como apoyo estratégico en marketing digital para investigar mercados \n            con mayor precisión, estructurar planes, crear contenido de forma \n            eficiente y optimizar campañas basándose en datos reales.</P></TD></TR>\n        <TR>\n          <TD \n          style="PADDING-BOTTOM: 30px; PADDING-TOP: 30px; PADDING-LEFT: 30px; PADDING-RIGHT: 30px; BACKGROUND-COLOR: rgb(255,255,255)" \n          align=center><A \n            style="FONT-SIZE: 16px; TEXT-DECORATION: none; TEXT-TRANSFORM: uppercase; FONT-WEIGHT: bold; COLOR: rgb(255,255,255); PADDING-BOTTOM: 16px; PADDING-TOP: 16px; PADDING-LEFT: 50px; DISPLAY: inline-block; LETTER-SPACING: 1px; PADDING-RIGHT: 50px; BACKGROUND-COLOR: rgb(234,88,12); border-radius: 10px; box-shadow: 0px 6px 20px rgba(234,88,12,0.4)" \n            href="https://wa.me/51959117612?text=Deseo%20informacion%20del%20Diplomado%20en%20Marketing%20Digital%20con%20IA%20em">&gt;&nbsp;PROMO \n            DISPONIBLE CLIC <U><FONT size=4>AQUÍ</FONT></U></A></TD></TR>\n        <TR>\n          <TD \n          style="PADDING-BOTTOM: 50px; PADDING-TOP: 20px; PADDING-LEFT: 50px; PADDING-RIGHT: 50px; BACKGROUND-COLOR: rgb(255,255,255)">\n            <H3 \n            style="FONT-SIZE: 22px; MARGIN-BOTTOM: 30px; TEXT-TRANSFORM: uppercase; COLOR: rgb(30,58,138); TEXT-ALIGN: left; PADDING-LEFT: 15px; BORDER-LEFT: rgb(37,99,235) 6px solid">CONTENIDO</H3>\n            <DIV \nstyle="FONT-SIZE: 14px; COLOR: rgb(51,65,85); LINE-HEIGHT: 1.8">\n            <P style="MARGIN: 0px"><STRONG style="COLOR: rgb(30,58,138)">Módulo \n            1: Fundamentos de Inteligencia Artificial para Marketing \n            Digital</STRONG><BR>Introducción a la Inteligencia Artificial<BR>o \n            Qué es la Inteligencia Artificial.<BR>o Qué es la IA \n            generativa.<BR>o Tipos de IA aplicadas al marketing: texto, imagen, \n            video y audio.<BR>o Cómo la IA transforma la planificación, creación \n            y optimización del marketing digital.<BR>LLMs aplicados al \n            marketing<BR>o Qué es un LLM.<BR>o Cómo funcionan los modelos de \n            lenguaje.<BR>o Diferencias entre ChatGPT, Gemini, Claude.<BR>o \n            Cuándo usar cada IA según el tipo de tarea.<BR>Prompt \n            Engineering<BR>o Qué es prompting.<BR>o Estructura profesional de \n            prompts.<BR>o Tipos de prompts aplicados a marketing.<BR>o Prompts \n            para investigación, estrategia, contenidos, campañas y \n            análisis.<BR>Introducción a agentes IA<BR>o Qué es un agente \n            IA.<BR>o Diferencia entre prompts y agentes.<BR>o Uso de proyectos \n            en ChatGPT y Claude.<BR>o Cómo organizar flujos de trabajo con \n            IA.<BR><BR><STRONG style="COLOR: rgb(30,58,138)">Módulo 2: \n            Investigación de Mercado y Cliente Ideal con \n            IA</STRONG><BR>Investigación estratégica con IA<BR>o Cómo investigar \n            mercados con LLMs.<BR>o Benchmark competitivo con IA.<BR>o \n            Identificación de oportunidades de negocio.<BR>o Análisis de \n            tendencias con IA.<BR>o Detección de problemas, necesidades y \n            comportamientos del mercado.<BR>Construcción del cliente ideal<BR>o \n            Buyer persona con IA.<BR>o Mapa de dolores y necesidades.<BR>o Mapa \n            de motivaciones de compra.<BR>o Objeciones frecuentes del \n            cliente.<BR>o Factores que influyen en la decisión de \n            compra.<BR>Segmentación estratégica<BR>o Segmentación B2C.<BR>o \n            Segmentación B2B.<BR>o Segmentación psicográfica.<BR>o Segmentación \n            comportamental.<BR>o Priorización de segmentos con mayor potencial \n            comercial.<BR>Taller práctico<BR>o Creación del perfil de cliente \n            ideal con IA.<BR>o Desarrollo de un análisis base de mercado y \n            competencia.<BR><BR><STRONG style="COLOR: rgb(30,58,138)">Módulo 3: \n            Propuesta de Valor, Posicionamiento y Plan Estratégico de \n            Marketing</STRONG><BR>Construcción de la propuesta de valor<BR>o \n            Identificación del problema principal.<BR>o Definición de la promesa \n            de valor.<BR>o Diferenciación competitiva.<BR>o Resultados esperados \n            del cliente.<BR>o Argumentos clave para comunicar \n            valor.<BR>Posicionamiento estratégico<BR>o Desarrollo del mensaje \n            central.<BR>o Ángulos de marketing.<BR>o Storyselling con IA.<BR>o \n            Adaptación del mensaje según público, canal y etapa del \n            funnel.<BR>Construcción del plan estratégico de marketing<BR>o \n            Definición de objetivos comerciales.<BR>o KPIs estratégicos.<BR>o \n            Selección de canales digitales.<BR>o Roadmap estratégico de \n            marketing de 90 días.<BR>o Priorización de acciones según impacto y \n            facilidad de ejecución.<BR>Taller práctico<BR>o Desarrollo de la \n            propuesta de valor.<BR>o Construcción del plan estratégico \n            base.<BR><BR><STRONG style="COLOR: rgb(30,58,138)">Módulo 4: Sistema \n            Digital de Captación y Conversión con IA</STRONG><BR>Arquitectura \n            del funnel de ventas<BR>o Estructura del funnel digital.<BR>o \n            Atracción.<BR>o Captura.<BR>o Nutrición.<BR>o Conversión.<BR>o \n            Fidelización.<BR>o Relación entre marketing, ventas y experiencia \n            del cliente.<BR>Customer journey estratégico<BR>o Puntos de contacto \n            digitales.<BR>o Diseño de la experiencia del cliente.<BR>o Mensajes \n            clave por etapa del recorrido.<BR>o Identificación de fricciones y \n            oportunidades de mejora.<BR>Lead magnets con IA<BR>o Tipos de lead \n            magnets.<BR>o Validación de ideas con IA.<BR>o Creación de lead \n            magnets orientados a conversión.<BR>o Alineación del lead magnet con \n            el cliente ideal y la propuesta de valor.<BR>Landing pages \n            orientadas a conversión<BR>o Elementos de una landing page \n            efectiva.<BR>o Estructura estratégica de una página de \n            captura..<BR>o Copywriting para landing pages con IA.<BR>o \n            Optimización de mensajes, beneficios y llamados a la \n            acción.<BR>Taller práctico<BR>o Diseño del funnel completo.<BR>o \n            Creación de la estructura de una landing page.<BR>o Desarrollo de \n            una propuesta de lead magnet.<BR><BR><STRONG \n            style="COLOR: rgb(30,58,138)">Módulo 5: Email Marketing, WhatsApp y \n            Seguimiento Comercial con IA</STRONG><BR>Email marketing \n            estratégico<BR>o Rol del email dentro del funnel de ventas.<BR>o \n            Tipos de emails: captación, nutrición, conversión y \n            fidelización.<BR>o Diferencia entre campañas puntuales y secuencias \n            de seguimiento.<BR>o Buenas prácticas para mejorar apertura, lectura \n            y respuesta.<BR>o Uso de IA para crear estructuras y versiones de \n            emails.<BR>Secuencias de emails con IA<BR>o Estructura de una \n            secuencia de emails.<BR>o Secuencias clave: bienvenida, nutrición, \n            venta y reactivación.<BR>o Personalización de mensajes según \n            segmento y etapa del prospecto.<BR>o Optimización de asuntos, \n            preheaders y llamados a la acción.<BR>o Adaptación del tono según \n            marca, público y objetivo comercial.<BR>Seguimiento comercial por \n            WhatsApp<BR>o Rol de WhatsApp dentro del proceso de ventas.<BR>o \n            Momentos clave para contactar a un prospecto.<BR>o Mensajes de \n            primer contacto, seguimiento, reactivación y cierre.<BR>o Uso de IA \n            para crear mensajes comerciales más claros y personalizados.<BR>o \n            Buenas prácticas para evitar mensajes invasivos o \n            repetitivos.<BR>Pipeline comercial en WhatsApp<BR>o Qué es un \n            pipeline comercial y por qué ayuda a ordenar el seguimiento.<BR>o \n            Etapas básicas: nuevo lead, contactado, interesado, propuesta \n            enviada, seguimiento, cierre ganado y cierre perdido.<BR>o \n            Clasificación de leads según interés, urgencia y oportunidad \n            comercial.<BR>o Priorización de prospectos y próximos pasos.<BR>o \n            Indicadores básicos: leads activos, tasa de respuesta, propuestas \n            enviadas y cierres.<BR>Taller práctico<BR>o Creación de una \n            secuencia básica de emails.<BR>o Desarrollo de mensajes de \n            seguimiento por WhatsApp.<BR>o Diseño de un pipeline comercial \n            simple.<BR>o Creación de plantillas para objeciones \n            frecuentes.<BR><BR><STRONG style="COLOR: rgb(30,58,138)">Módulo 6: \n            Estrategia de Contenidos, SEO y Redes Sociales con IA</STRONG><BR>1. \n            Estrategia de contenidos orientada a ventas<BR>o Contenido según el \n            funnel: TOFU, MOFU y BOFU.<BR>o Pilares de contenido alineados al \n            cliente ideal y propuesta de valor.<BR>o Diferencia entre contenido \n            educativo, de autoridad, confianza y conversión.<BR>o Relación entre \n            contenido, marca y generación de demanda.<BR>2. Creación de \n            contenido con IA para redes sociales<BR>o Generación de ideas de \n            contenido con IA.<BR>o Creación de posts para redes sociales.<BR>o \n            Adaptación de mensajes por canal y formato.<BR>o Reutilización de \n            contenidos con IA.<BR>3. SEO práctico con IA<BR>o Ideación de temas \n            SEO con IA.<BR>o Estructura básica de artículos optimizados.<BR>o \n            Optimización de títulos, subtítulos y descripciones.<BR>o Creación \n            de contenidos para atraer tráfico calificado.<BR>4. Planificación de \n            contenidos<BR>o Calendario editorial mensual.<BR>o Priorización de \n            contenidos según objetivos comerciales.<BR>o Organización simple del \n            flujo de producción de contenido.<BR>Taller práctico<BR>o Desarrollo \n            de un calendario mensual de contenidos.<BR>o Creación de piezas base \n            para redes sociales.<BR>o Estructura de un artículo SEO.<BR>o \n            Adaptación de una pieza de contenido a distintos \n            formatos.<BR><BR><STRONG style="COLOR: rgb(30,58,138)">Módulo 7: \n            Creatividad Visual, Imágenes y Video Marketing con IA</STRONG><BR>1. \n            Creatividad visual aplicada al marketing<BR>o Traducción de mensajes \n            comerciales en ideas visuales.<BR>o Desarrollo de conceptos \n            creativos para contenidos y campañas.<BR>o Relación entre mensaje, \n            formato y objetivo comercial.<BR>2. Creación de imágenes con IA<BR>o \n            Generación de imágenes con ChatGPT o Gemini.<BR>o Creación de \n            imágenes para redes sociales.<BR>o Variantes visuales simples para \n            pruebas creativas.<BR>3. Video marketing con IA<BR>o Tipos de videos \n            según objetivo: educativo, autoridad, publicitario y \n            conversión.<BR>o Creación de guiones cortos para video con IA.<BR>o \n            Adaptación de una idea visual a formato video.<BR>4. Producción \n            audiovisual básica con IA<BR>o Flujo simple de producción: idea, \n            guion, imagen/video y publicación.<BR>Taller práctico<BR>o \n            Desarrollo de un concepto visual.<BR>o Creación de una imagen base \n            con IA.<BR>o Creación de un guion corto.<BR>o Producción de una \n            pieza audiovisual simple con IA.<BR><BR><STRONG \n            style="COLOR: rgb(30,58,138)">Módulo 8: Publicidad Digital y \n            Analítica con IA</STRONG><BR>Estrategia de campañas digitales<BR>o \n            Arquitectura de campañas digitales.<BR>o Definición de \n            audiencias.<BR>o Ángulos publicitarios.<BR>o Selección de \n            plataformas según objetivo comercial.<BR>o Meta Ads.<BR>o Linkedin \n            Ads.<BR>o Google Ads.<BR>Copywriting publicitario con IA<BR>o Hooks \n            publicitarios.<BR>o Beneficios vs características.<BR>o Llamados a \n            la acción efectivos.<BR>o Creación de variaciones de anuncios con \n            IA.<BR>o Adaptación del copy según plataforma y etapa del \n            funnel.<BR>Creativos publicitarios con IA<BR>o Creación de conceptos \n            visuales.<BR>o Generación de imágenes publicitarias.<BR>o Variantes \n            creativas.<BR>o Relación entre mensaje, formato y objetivo de \n            campaña.<BR>Testing y optimización<BR>o Variaciones de \n            anuncios.<BR>o Introducción al testing A/B.<BR>o Optimización de \n            campañas.<BR>Analítica de marketing con IA<BR>o Marketing basado en \n            datos.<BR>o KPIs clave de marketing: CAC, ROAS, CTR, Conversion Rate \n            y CPL.<BR>o Interpretación de resultados con IA.<BR>Taller práctico \n            final<BR>o Desarrollo de una ficha estratégica de campaña.<BR>o \n            Análisis de métricas y oportunidades de optimización.<BR><BR><STRONG \n            style="COLOR: rgb(30,58,138)">Módulo 9: Análisis de Datos y \n            Estadística Aplicada a Marketing y Ventas con Inteligencia \n            Artificial (DIEGO MIRANDA - CHILE)</STRONG><BR>A) Fundamentos de \n            Datos en Marketing y Ventas<BR>o Introducción al análisis de datos \n            en negocios<BR>o Tipos de datos en marketing:<BR>o Datos de \n            clientes<BR>o Datos de ventas<BR>o Datos de comportamiento<BR>o \n            Principales indicadores (KPIs):<BR>o Ventas totales<BR>o Frecuencia \n            de compra<BR>o Tasa de conversión<BR>o Flujo de valor:<BR>o Datos - \n            Información - Decisiones<BR>Actividad práctica:<BR>o Análisis \n            inicial de un dataset de ventas:<BR>o Identificación de \n            variables<BR>o Cálculo de ventas totales<BR>o Identificación del \n            producto más vendido<BR>B) Análisis Exploratorio de Datos (EDA) \n            aplicado a Negocio<BR>o Estadística descriptiva:<BR>o Media<BR>o \n            Mediana<BR>o Desviación estándar<BR>o Análisis por \n            segmentación:<BR>o Clientes por edad<BR>o Clientes por región<BR>o \n            Clientes por frecuencia de compra<BR>o Visualización de datos:<BR>o \n            Ventas por fecha<BR>o Ventas por producto<BR>o Distribución de \n            clientes<BR>Herramientas:<BR>o Python (Pandas, Matplotlib)<BR>o \n            Actividad práctica:<BR>o Identificación de:<BR>o Clientes frecuentes \n            vs ocasionales<BR>o Productos más rentables<BR>o Días de mayor \n            venta<BR>o Generación de gráficos simples<BR>C) Inteligencia \n            Artificial aplicada a Marketing y Ventas<BR>1. Segmentación de \n            clientes (Clustering)<BR>o Introducción a K-Means<BR>o Agrupación \n            automática de clientes<BR>o Interpretación de segmentos:<BR>o \n            Clientes premium<BR>o Clientes ocasionales<BR>o Clientes sensibles \n            al precio<BR>2. Predicción de ventas<BR>o Introducción a modelos \n            predictivos<BR>o Variables relevantes:<BR>o Tiempo (fecha)<BR>o \n            Promociones<BR>o Historial de ventas<BR>o Modelos simples:<BR>o \n            Regresión<BR>o Árboles de decisión<BR>3. Sistemas de \n            recomendación<BR>o Concepto:<BR>o "Clientes similares compran \n            productos similares"<BR>o Aplicación básica en ventas<BR>Actividad \n            práctica:<BR>o Segmentación de clientes mediante clustering<BR>o \n            Construcción de un modelo simple de predicción<BR>o Interpretación \n            de resultados<BR>D) Toma de Decisiones Basadas en Datos<BR>o \n            Transformación de análisis en estrategias:<BR>o Segmentación de \n            campañas<BR>o Optimización de inventario<BR>o Identificación de \n            oportunidades de venta<BR>o Casos de uso:<BR>o Aumento de \n            ventas<BR>o Reducción de costos<BR>o Mejora de \n            conversión<BR>Herramientas Utilizadas en el curso<BR>o Python \n            (Google Colab recomendado)<BR>o Librerías:<BR>o pandas<BR>o \n            numpy<BR>o matplotlib<BR>o scikit-learn<BR><BR><STRONG \n            style="COLOR: rgb(30,58,138)">Módulo Extra: Vibe Coding para Landing \n            Pages, Webs, E-commerce y CRM con IA</STRONG><BR>1. Introducción al \n            Vibe Coding y criterios de implementación<BR>o Qué es Vibe \n            Coding.<BR>o Cómo crear soluciones digitales usando instrucciones en \n            lenguaje natural.<BR>o Casos de uso en marketing, ventas y captación \n            de clientes.<BR>o Herramientas del módulo: Claude Code, Codex y \n            Antigravity.<BR>o Cuándo usar código directo y cuándo usar \n            WordPress.<BR>o Criterios de decisión: velocidad, flexibilidad, \n            mantenimiento, escalabilidad y nivel de personalización.<BR>2. \n            Creación de Landing Pages con IA<BR>o Estructura de una landing page \n            orientada a conversión.<BR>o Generación de copywriting con IA.<BR>o \n            Creación de formularios y captación de contactos.<BR>o Desarrollo \n            asistido con Claude Code, Codex y Antigravity.<BR>o Optimización \n            básica para campañas y funnels de venta.<BR>3. Creación de una \n            página web corporativa con IA<BR>o Estructura web: inicio, \n            servicios, nosotros, contacto y CTA.<BR>o Arquitectura de navegación \n            y experiencia del usuario.<BR>o Generación de textos, secciones y \n            contenido can IA.<BR>o Adaptación del proyecto a código directo o \n            WordPress.<BR>4. Creación de una tienda online con IA<BR>o \n            Estructura comercial de una tienda online.<BR>o Catálogo, \n            categorías, fichas de producto y carrito.<BR>o Generación de \n            descripciones y contenido de producto con IA.<BR>o Implementación \n            con WordPress o código directo según el caso.<BR>5. Integración de \n            chat web inteligente, CRM e IA<BR>o Diseño del flujo conversacional. \n            <FONT color=#ffffff>proyectosdestaperapidocl</FONT><BR>o Creación de una base \n            de conocimiento para atención automática.<BR>o Integración del chat \n            en landing pages, webs y tiendas online.<BR>o Captura automática de \n            leads desde formularios y chats.<BR>o Registro y organización de \n            contactos en CRM.<BR>o Clasificación de prospectos y seguimiento \n            comercial con IA.</P></DIV></TD></TR>\n        <TR>\n          <TD \n          style="BORDER-TOP: rgb(226,232,240) 1px solid; PADDING-BOTTOM: 50px; PADDING-TOP: 50px; PADDING-LEFT: 20px; PADDING-RIGHT: 20px; BACKGROUND-COLOR: rgb(239,246,255)" \n          align=center>\n            <P \n            style="FONT-SIZE: 14px; MARGIN-BOTTOM: 25px; TEXT-TRANSFORM: uppercase; COLOR: rgb(30,64,175); LETTER-SPACING: 1px">Inscripciones \n            abiertas vía WhatsApp al<SPAN>&nbsp;</SPAN><SPAN \n            style="FONT-WEIGHT: 900; COLOR: rgb(30,58,138)">+51959117612</SPAN></P><A \n            style="FONT-SIZE: 18px; TEXT-DECORATION: none; FONT-WEIGHT: bold; COLOR: rgb(255,255,255); PADDING-BOTTOM: 22px; PADDING-TOP: 22px; PADDING-LEFT: 60px; DISPLAY: inline-block; PADDING-RIGHT: 60px; BACKGROUND-COLOR: rgb(234,88,12); border-radius: 50px; box-shadow: 0px 10px 25px rgba(234,88,12,0.3)" \n            href="https://wa.me/51959117612?text=Deseo%20informacion%20del%20Diplomado%20en%20Marketing%20Digital%20con%20IA%20em">&gt;MÁS \n            INFORMACIÓN CLIC <FONT size=4><U>AQUÍ</U></FONT></A></TD></TR>\n        <TR>\n          <TD \n          style="FONT-SIZE: 14px; COLOR: rgb(255,255,255); PADDING-BOTTOM: 40px; PADDING-TOP: 40px; PADDING-LEFT: 25px; LINE-HEIGHT: 1.6; PADDING-RIGHT: 25px; BACKGROUND-COLOR: rgb(15,23,42)" \n          align=center><STRONG>ELC - Escuela Latinoamericana de \n            Capacitación</STRONG><BR>Liderando la \n      transformación</TD></TR></TBODY></TABLE></TD></TR></TBODY></TABLE></DIV></FONT><FONT \nsize=1></FONT></DIV></DIV></DIV></DIV>\n<DIV>\n<DIV><FONT size=1></FONT>&nbsp;</DIV>\n<DIV><FONT size=1>Si no desea recibir nuestros mensajes puede pedir \ndesuscribirse haciendo click <A \nhref="mailto:out@vladns.com">ACA</A></FONT></DIV></DIV></DIV></BODY></HTML>\n\n','\n',char(10)),'destaperapido.cl','bloqueado','2026-08-08T23:39:50.000Z','2026-08-08 23:42:07',NULL,NULL,NULL,NULL,NULL,1,NULL,0,NULL,NULL,'edf84f3ac7359d4a6bfa3656c38ee8bd990de9d8d9d182b8b69d6ca081784130','s:dipiomado en marketing aplicando ia - gestión comercial, webs, análisis datos, mkt de contenido..|it@vladns.com',NULL,NULL,0,NULL,NULL,NULL);
INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(576,'<6892DA2580547A99454009B7133426B2@134.195.208.17>','it@vladns.com','contacto@destaperapido.cl','DipIomado en Marketing aplicando IA - Gestión Comercial, Webs, Análisis Datos, Mkt de Contenido..',replace('  \nE L C\nDIPLOMADO EN\nMARKETING DIGITAL CON INTELIGENCIA ARTIFICIAL \n- AI MARKETING STRATEGY\n¡Cómo convertir la Inteligencia Artificial en el copiloto estratégico para marketing digital y ventas para escalar tu negocio!\nFECHAS DE INICIO: 12 DE AGOSTO\nEn el horario de 7:00 pm a 10:00 pm\nDuración 33 horas o Lunes, Miércoles y Viernes o Horario GMT-5 para: Perú, Colombia, Ecuador, Panamá \nINCLUYE: Material digital del tema a desarrollar, Asistencia Permanente del Expositor durante la capacitación, Link con la grabación de la clase y certificado digital.\nLa inteligencia artificial está transformando la forma en que las empresas planifican su marketing, atraen clientes y optimizan sus resultados comerciales. Este diplomado te permitirá utilizar la IA como apoyo estratégico en marketing digital para investigar mercados con mayor precisión, estructurar planes, crear contenido de forma eficiente y optimizar campañas basándose en datos reales.\n> PROMO DISPONIBLE CLIC AQUÍ\nCONTENIDO\nMódulo 1: Fundamentos de Inteligencia Artificial para Marketing Digital\nIntroducción a la Inteligencia Artificial\no Qué es la Inteligencia Artificial.\no Qué es la IA generativa.\no Tipos de IA aplicadas al marketing: texto, imagen, video y audio.\no Cómo la IA transforma la planificación, creación y optimización del marketing digital.\nLLMs aplicados al marketing\no Qué es un LLM.\no Cómo funcionan los modelos de lenguaje.\no Diferencias entre ChatGPT, Gemini, Claude.\no Cuándo usar cada IA según el tipo de tarea.\nPrompt Engineering\no Qué es prompting.\no Estructura profesional de prompts.\no Tipos de prompts aplicados a marketing.\no Prompts para investigación, estrategia, contenidos, campañas y análisis.\nIntroducción a agentes IA\no Qué es un agente IA.\no Diferencia entre prompts y agentes.\no Uso de proyectos en ChatGPT y Claude.\no Cómo organizar flujos de trabajo con IA.\n\nMódulo 2: Investigación de Mercado y Cliente Ideal con IA\nInvestigación estratégica con IA\no Cómo investigar mercados con LLMs.\no Benchmark competitivo con IA.\no Identificación de oportunidades de negocio.\no Análisis de tendencias con IA.\no Detección de problemas, necesidades y comportamientos del mercado.\nConstrucción del cliente ideal\no Buyer persona con IA.\no Mapa de dolores y necesidades.\no Mapa de motivaciones de compra.\no Objeciones frecuentes del cliente.\no Factores que influyen en la decisión de compra.\nSegmentación estratégica\no Segmentación B2C.\no Segmentación B2B.\no Segmentación psicográfica.\no Segmentación comportamental.\no Priorización de segmentos con mayor potencial comercial.\nTaller práctico\no Creación del perfil de cliente ideal con IA.\no Desarrollo de un análisis base de mercado y competencia.\n\nMódulo 3: Propuesta de Valor, Posicionamiento y Plan Estratégico de Marketing\nConstrucción de la propuesta de valor\no Identificación del problema principal.\no Definición de la promesa de valor.\no Diferenciación competitiva.\no Resultados esperados del cliente.\no Argumentos clave para comunicar valor.\nPosicionamiento estratégico\no Desarrollo del mensaje central.\no Ángulos de marketing.\no Storyselling con IA.\no Adaptación del mensaje según público, canal y etapa del funnel.\nConstrucción del plan estratégico de marketing\no Definición de objetivos comerciales.\no KPIs estratégicos.\no Selección de canales digitales.\no Roadmap estratégico de marketing de 90 días.\no Priorización de acciones según impacto y facilidad de ejecución.\nTaller práctico\no Desarrollo de la propuesta de valor.\no Construcción del plan estratégico base.\n\nMódulo 4: Sistema Digital de Captación y Conversión con IA\nArquitectura del funnel de ventas\no Estructura del funnel digital.\no Atracción.\no Captura.\no Nutrición.\no Conversión.\no Fidelización.\no Relación entre marketing, ventas y experiencia del cliente.\nCustomer journey estratégico\no Puntos de contacto digitales.\no Diseño de la experiencia del cliente.\no Mensajes clave por etapa del recorrido.\no Identificación de fricciones y oportunidades de mejora.\nLead magnets con IA\no Tipos de lead magnets.\no Validación de ideas con IA.\no Creación de lead magnets orientados a conversión.\no Alineación del lead magnet con el cliente ideal y la propuesta de valor.\nLanding pages orientadas a conversión\no Elementos de una landing page efectiva.\no Estructura estratégica de una página de captura..\no Copywriting para landing pages con IA.\no Optimización de mensajes, beneficios y llamados a la acción.\nTaller práctico\no Diseño del funnel completo.\no Creación de la estructura de una landing page.\no Desarrollo de una propuesta de lead magnet.\n\nMódulo 5: Email Marketing, WhatsApp y Seguimiento Comercial con IA\nEmail marketing estratégico\no Rol del email dentro del funnel de ventas.\no Tipos de emails: captación, nutrición, conversión y fidelización.\no Diferencia entre campañas puntuales y secuencias de seguimiento.\no Buenas prácticas para mejorar apertura, lectura y respuesta.\no Uso de IA para crear estructuras y versiones de emails.\nSecuencias de emails con IA\no Estructura de una secuencia de emails.\no Secuencias clave: bienvenida, nutrición, venta y reactivación.\no Personalización de mensajes según segmento y etapa del prospecto.\no Optimización de asuntos, preheaders y llamados a la acción.\no Adaptación del tono según marca, público y objetivo comercial.\nSeguimiento comercial por WhatsApp\no Rol de WhatsApp dentro del proceso de ventas.\no Momentos clave para contactar a un prospecto.\no Mensajes de primer contacto, seguimiento, reactivación y cierre.\no Uso de IA para crear mensajes comerciales más claros y personalizados.\no Buenas prácticas para evitar mensajes invasivos o repetitivos.\nPipeline comercial en WhatsApp\no Qué es un pipeline comercial y por qué ayuda a ordenar el seguimiento.\no Etapas básicas: nuevo lead, contactado, interesado, propuesta enviada, seguimiento, cierre ganado y cierre perdido.\no Clasificación de leads según interés, urgencia y oportunidad comercial.\no Priorización de prospectos y próximos pasos.\no Indicadores básicos: leads activos, tasa de respuesta, propuestas enviadas y cierres.\nTaller práctico\no Creación de una secuencia básica de emails.\no Desarrollo de mensajes de seguimiento por WhatsApp.\no Diseño de un pipeline comercial simple.\no Creación de plantillas para objeciones frecuentes.\n\nMódulo 6: Estrategia de Contenidos, SEO y Redes Sociales con IA\n1. Estrategia de contenidos orientada a ventas\no Contenido según el funnel: TOFU, MOFU y BOFU.\no Pilares de contenido alineados al cliente ideal y propuesta de valor.\no Diferencia entre contenido educativo, de autoridad, confianza y conversión.\no Relación entre contenido, marca y generación de demanda.\n2. Creación de contenido con IA para redes sociales\no Generación de ideas de contenido con IA.\no Creación de posts para redes sociales.\no Adaptación de mensajes por canal y formato.\no Reutilización de contenidos con IA.\n3. SEO práctico con IA\no Ideación de temas SEO con IA.\no Estructura básica de artículos optimizados.\no Optimización de títulos, subtítulos y descripciones.\no Creación de contenidos para atraer tráfico calificado.\n4. Planificación de contenidos\no Calendario editorial mensual.\no Priorización de contenidos según objetivos comerciales.\no Organización simple del flujo de producción de contenido.\nTaller práctico\no Desarrollo de un calendario mensual de contenidos.\no Creación de piezas base para redes sociales.\no Estructura de un artículo SEO.\no Adaptación de una pieza de contenido a distintos formatos.\n\nMódulo 7: Creatividad Visual, Imágenes y Video Marketing con IA\n1. Creatividad visual aplicada al marketing\no Traducción de mensajes comerciales en ideas visuales.\no Desarrollo de conceptos creativos para contenidos y campañas.\no Relación entre mensaje, formato y objetivo comercial.\n2. Creación de imágenes con IA\no Generación de imágenes con ChatGPT o Gemini.\no Creación de imágenes para redes sociales.\no Variantes visuales simples para pruebas creativas.\n3. Video marketing con IA\no Tipos de videos según objetivo: educativo, autoridad, publicitario y conversión.\no Creación de guiones cortos para video con IA.\no Adaptación de una idea visual a formato video.\n4. Producción audiovisual básica con IA\no Flujo simple de producción: idea, guion, imagen/video y publicación.\nTaller práctico\no Desarrollo de un concepto visual.\no Creación de una imagen base con IA.\no Creación de un guion corto.\no Producción de una pieza audiovisual simple con IA.\n\nMódulo 8: Publicidad Digital y Analítica con IA\nEstrategia de campañas digitales\no Arquitectura de campañas digitales.\no Definición de audiencias.\no Ángulos publicitarios.\no Selección de plataformas según objetivo comercial.\no Meta Ads.\no Linkedin Ads.\no Google Ads.\nCopywriting publicitario con IA\no Hooks publicitarios.\no Beneficios vs características.\no Llamados a la acción efectivos.\no Creación de variaciones de anuncios con IA.\no Adaptación del copy según plataforma y etapa del funnel.\nCreativos publicitarios con IA\no Creación de conceptos visuales.\no Generación de imágenes publicitarias.\no Variantes creativas.\no Relación entre mensaje, formato y objetivo de campaña.\nTesting y optimización\no Variaciones de anuncios.\no Introducción al testing A/B.\no Optimización de campañas.\nAnalítica de marketing con IA\no Marketing basado en datos.\no KPIs clave de marketing: CAC, ROAS, CTR, Conversion Rate y CPL.\no Interpretación de resultados con IA.\nTaller práctico final\no Desarrollo de una ficha estratégica de campaña.\no Análisis de métricas y oportunidades de optimización.\n\nMódulo 9: Análisis de Datos y Estadística Aplicada a Marketing y Ventas con Inteligencia Artificial (DIEGO MIRANDA - CHILE)\nA) Fundamentos de Datos en Marketing y Ventas\no Introducción al análisis de datos en negocios\no Tipos de datos en marketing:\no Datos de clientes\no Datos de ventas\no Datos de comportamiento\no Principales indicadores (KPIs):\no Ventas totales\no Frecuencia de compra\no Tasa de conversión\no Flujo de valor:\no Datos - Información - Decisiones\nActividad práctica:\no Análisis inicial de un dataset de ventas:\no Identificación de variables\no Cálculo de ventas totales\no Identificación del producto más vendido\nB) Análisis Exploratorio de Datos (EDA) aplicado a Negocio\no Estadística descriptiva:\no Media\no Mediana\no Desviación estándar\no Análisis por segmentación:\no Clientes por edad\no Clientes por región\no Clientes por frecuencia de compra\no Visualización de datos:\no Ventas por fecha\no Ventas por producto\no Distribución de clientes\nHerramientas:\no Python (Pandas, Matplotlib)\no Actividad práctica:\no Identificación de:\no Clientes frecuentes vs ocasionales\no Productos más rentables\no Días de mayor venta\no Generación de gráficos simples\nC) Inteligencia Artificial aplicada a Marketing y Ventas\n1. Segmentación de clientes (Clustering)\no Introducción a K-Means\no Agrupación automática de clientes\no Interpretación de segmentos:\no Clientes premium\no Clientes ocasionales\no Clientes sensibles al precio\n2. Predicción de ventas\no Introducción a modelos predictivos\no Variables relevantes:\no Tiempo (fecha)\no Promociones\no Historial de ventas\no Modelos simples:\no Regresión\no Árboles de decisión\n3. Sistemas de recomendación\no Concepto:\no "Clientes similares compran productos similares"\no Aplicación básica en ventas\nActividad práctica:\no Segmentación de clientes mediante clustering\no Construcción de un modelo simple de predicción\no Interpretación de resultados\nD) Toma de Decisiones Basadas en Datos\no Transformación de análisis en estrategias:\no Segmentación de campañas\no Optimización de inventario\no Identificación de oportunidades de venta\no Casos de uso:\no Aumento de ventas\no Reducción de costos\no Mejora de conversión\nHerramientas Utilizadas en el curso\no Python (Google Colab recomendado)\no Librerías:\no pandas\no numpy\no matplotlib\no scikit-learn\n\nMódulo Extra: Vibe Coding para Landing Pages, Webs, E-commerce y CRM con IA\n1. Introducción al Vibe Coding y criterios de implementación\no Qué es Vibe Coding.\no Cómo crear soluciones digitales usando instrucciones en lenguaje natural.\no Casos de uso en marketing, ventas y captación de clientes.\no Herramientas del módulo: Claude Code, Codex y Antigravity.\no Cuándo usar código directo y cuándo usar WordPress.\no Criterios de decisión: velocidad, flexibilidad, mantenimiento, escalabilidad y nivel de personalización.\n2. Creación de Landing Pages con IA\no Estructura de una landing page orientada a conversión.\no Generación de copywriting con IA.\no Creación de formularios y captación de contactos.\no Desarrollo asistido con Claude Code, Codex y Antigravity.\no Optimización básica para campañas y funnels de venta.\n3. Creación de una página web corporativa con IA\no Estructura web: inicio, servicios, nosotros, contacto y CTA.\no Arquitectura de navegación y experiencia del usuario.\no Generación de textos, secciones y contenido can IA.\no Adaptación del proyecto a código directo o WordPress.\n4. Creación de una tienda online con IA\no Estructura comercial de una tienda online.\no Catálogo, categorías, fichas de producto y carrito.\no Generación de descripciones y contenido de producto con IA.\no Implementación con WordPress o código directo según el caso.\n5. Integración de chat web inteligente, CRM e IA\no Diseño del flujo conversacional. contactodestaperapidocl\no Creación de una base de conocimiento para atención automática.\no Integración del chat en landing pages, webs y tiendas online.\no Captura automática de leads desde formularios y chats.\no Registro y organización de contactos en CRM.\no Clasificación de prospectos y seguimiento comercial con IA.\nInscripciones abiertas vía WhatsApp al +51959117612\n>MÁS INFORMACIÓN CLIC AQUÍ\nELC - Escuela Latinoamericana de Capacitación\nLiderando la transformación\n\n\n\nSi no desea recibir nuestros mensajes puede pedir desuscribirse haciendo click ACA\n\n','\n',char(10)),replace('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0 Transitional//EN">\n<HTML><HEAD>\n<META content="text/html; charset=iso-8859-1" http-equiv=Content-Type>\n<META name=GENERATOR content="MSHTML 11.00.9600.17105">\n<STYLE></STYLE>\n</HEAD>\n<BODY bgColor=#ffffff>\n<DIV>\n<DIV>\n<DIV><FONT size=1>\n<DIV>&nbsp; \n<DIV>\n<DIV>\n<TABLE \nstyle=''FONT-FAMILY: "Segoe UI", Arial, sans-serif; WORD-SPACING: 0px; TEXT-TRANSFORM: none; ORPHANS: 2; WIDOWS: 2; LETTER-SPACING: normal; BACKGROUND-COLOR: rgb(248,250,252); -webkit-text-stroke-width: 0px; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial'' \ncellSpacing=0 cellPadding=0 width="100%" border=0>\n  <TBODY>\n  <TR>\n    <TD \n    style="PADDING-BOTTOM: 40px; PADDING-TOP: 40px; PADDING-LEFT: 0px; PADDING-RIGHT: 0px" \n    align=center>\n      <TABLE \n      style="OVERFLOW: hidden; BACKGROUND-COLOR: rgb(255,255,255); border-radius: 20px; box-shadow: 0px 15px 30px rgba(0,0,0,0.15)" \n      cellSpacing=0 cellPadding=0 width=650 border=0>\n        <TBODY>\n        <TR>\n          <TD \n          style="FONT-SIZE: 14px; FONT-WEIGHT: bold; COLOR: rgb(255,255,255); PADDING-BOTTOM: 18px; PADDING-TOP: 18px; PADDING-LEFT: 18px; LETTER-SPACING: 4px; PADDING-RIGHT: 18px; BACKGROUND-COLOR: rgb(15,23,42)" \n          align=center>E L C</TD></TR>\n        <TR>\n          <TD \n          style="BORDER-BOTTOM: rgb(37,99,235) 4px solid; PADDING-BOTTOM: 65px; PADDING-TOP: 65px; PADDING-LEFT: 40px; PADDING-RIGHT: 40px; BACKGROUND-COLOR: rgb(30,58,138)" \n          align=center>\n            <H1 \n            style="FONT-SIZE: 28px; TEXT-TRANSFORM: uppercase; FONT-WEIGHT: 900; COLOR: rgb(255,255,255); MARGIN: 0px; LINE-HEIGHT: 1.2"><SPAN \n            lang=ES-PE>\n            <P>DIPLOMADO EN</P></SPAN><SPAN \n            style="FONT-SIZE: 21pt; COLOR: rgb(96,165,250)"><SPAN \n            lang=ES-PE>MARKETING DIGITAL CON INTELIGENCIA \n            ARTIFICIAL</SPAN></SPAN>&nbsp;<BR><SPAN lang=ES-PE>- AI MARKETING \n            STRATEGY</SPAN></H1>\n            <H2 \n            style="FONT-SIZE: 16px; FONT-WEIGHT: 700; COLOR: rgb(255,255,255); MARGIN: 20px 0px 25px; LETTER-SPACING: 0px; LINE-HEIGHT: 1.4"><SPAN \n            lang=ES-PE>\n            <P>¡Cómo convertir la Inteligencia Artificial en el copiloto \n            estratégico para marketing digital y ventas para escalar tu \n            negocio!</P></SPAN></H2>\n            <DIV \n            style="FONT-SIZE: 16px; MAX-WIDTH: 540px; COLOR: rgb(219,234,254); LINE-HEIGHT: 1.5"><STRONG \n            style="TEXT-TRANSFORM: uppercase; COLOR: rgb(255,255,255)">FECHAS DE \n            INICIO: 12 DE<SPAN>&nbsp;</SPAN></STRONG><STRONG><SPAN \n            style="TEXT-TRANSFORM: uppercase; COLOR: rgb(255,255,255)">AGOSTO</SPAN></STRONG><BR><SPAN>En \n            el horario de 7:00 pm a 10:00 pm</SPAN><BR><SPAN \n            style="FONT-SIZE: 14px; FONT-WEIGHT: 600; COLOR: rgb(96,165,250)">Duración \n            33 horas o Lunes, Miércoles y Viernes o Horario GMT-5 para: Perú, \n            Colombia, Ecuador, Panamá</SPAN> \n            <P \n            style="FONT-SIZE: 11px; TEXT-TRANSFORM: uppercase; COLOR: rgb(148,163,184); MARGIN: 15px 0px 0px; LINE-HEIGHT: 1.4"><STRONG>INCLUYE:</STRONG><SPAN>&nbsp;</SPAN>Material \n            digital del tema a desarrollar, Asistencia Permanente del Expositor \n            durante la capacitación, Link con la grabación de la clase y \n            certificado digital.</P></DIV></TD></TR>\n        <TR>\n          <TD \n          style="PADDING-BOTTOM: 10px; TEXT-ALIGN: center; PADDING-TOP: 45px; PADDING-LEFT: 50px; PADDING-RIGHT: 50px; BACKGROUND-COLOR: rgb(255,255,255)">\n            <P \n            style="FONT-SIZE: 16px; COLOR: rgb(51,65,85); MARGIN: 0px; LINE-HEIGHT: 1.7">La \n            inteligencia artificial está transformando la forma en que las \n            empresas planifican su marketing, atraen clientes y optimizan sus \n            resultados comerciales. Este diplomado te permitirá utilizar la IA \n            como apoyo estratégico en marketing digital para investigar mercados \n            con mayor precisión, estructurar planes, crear contenido de forma \n            eficiente y optimizar campañas basándose en datos reales.</P></TD></TR>\n        <TR>\n          <TD \n          style="PADDING-BOTTOM: 30px; PADDING-TOP: 30px; PADDING-LEFT: 30px; PADDING-RIGHT: 30px; BACKGROUND-COLOR: rgb(255,255,255)" \n          align=center><A \n            style="FONT-SIZE: 16px; TEXT-DECORATION: none; TEXT-TRANSFORM: uppercase; FONT-WEIGHT: bold; COLOR: rgb(255,255,255); PADDING-BOTTOM: 16px; PADDING-TOP: 16px; PADDING-LEFT: 50px; DISPLAY: inline-block; LETTER-SPACING: 1px; PADDING-RIGHT: 50px; BACKGROUND-COLOR: rgb(234,88,12); border-radius: 10px; box-shadow: 0px 6px 20px rgba(234,88,12,0.4)" \n            href="https://wa.me/51959117612?text=Deseo%20informacion%20del%20Diplomado%20en%20Marketing%20Digital%20con%20IA%20em">&gt;&nbsp;PROMO \n            DISPONIBLE CLIC <U><FONT size=4>AQUÍ</FONT></U></A></TD></TR>\n        <TR>\n          <TD \n          style="PADDING-BOTTOM: 50px; PADDING-TOP: 20px; PADDING-LEFT: 50px; PADDING-RIGHT: 50px; BACKGROUND-COLOR: rgb(255,255,255)">\n            <H3 \n            style="FONT-SIZE: 22px; MARGIN-BOTTOM: 30px; TEXT-TRANSFORM: uppercase; COLOR: rgb(30,58,138); TEXT-ALIGN: left; PADDING-LEFT: 15px; BORDER-LEFT: rgb(37,99,235) 6px solid">CONTENIDO</H3>\n            <DIV \nstyle="FONT-SIZE: 14px; COLOR: rgb(51,65,85); LINE-HEIGHT: 1.8">\n            <P style="MARGIN: 0px"><STRONG style="COLOR: rgb(30,58,138)">Módulo \n            1: Fundamentos de Inteligencia Artificial para Marketing \n            Digital</STRONG><BR>Introducción a la Inteligencia Artificial<BR>o \n            Qué es la Inteligencia Artificial.<BR>o Qué es la IA \n            generativa.<BR>o Tipos de IA aplicadas al marketing: texto, imagen, \n            video y audio.<BR>o Cómo la IA transforma la planificación, creación \n            y optimización del marketing digital.<BR>LLMs aplicados al \n            marketing<BR>o Qué es un LLM.<BR>o Cómo funcionan los modelos de \n            lenguaje.<BR>o Diferencias entre ChatGPT, Gemini, Claude.<BR>o \n            Cuándo usar cada IA según el tipo de tarea.<BR>Prompt \n            Engineering<BR>o Qué es prompting.<BR>o Estructura profesional de \n            prompts.<BR>o Tipos de prompts aplicados a marketing.<BR>o Prompts \n            para investigación, estrategia, contenidos, campañas y \n            análisis.<BR>Introducción a agentes IA<BR>o Qué es un agente \n            IA.<BR>o Diferencia entre prompts y agentes.<BR>o Uso de proyectos \n            en ChatGPT y Claude.<BR>o Cómo organizar flujos de trabajo con \n            IA.<BR><BR><STRONG style="COLOR: rgb(30,58,138)">Módulo 2: \n            Investigación de Mercado y Cliente Ideal con \n            IA</STRONG><BR>Investigación estratégica con IA<BR>o Cómo investigar \n            mercados con LLMs.<BR>o Benchmark competitivo con IA.<BR>o \n            Identificación de oportunidades de negocio.<BR>o Análisis de \n            tendencias con IA.<BR>o Detección de problemas, necesidades y \n            comportamientos del mercado.<BR>Construcción del cliente ideal<BR>o \n            Buyer persona con IA.<BR>o Mapa de dolores y necesidades.<BR>o Mapa \n            de motivaciones de compra.<BR>o Objeciones frecuentes del \n            cliente.<BR>o Factores que influyen en la decisión de \n            compra.<BR>Segmentación estratégica<BR>o Segmentación B2C.<BR>o \n            Segmentación B2B.<BR>o Segmentación psicográfica.<BR>o Segmentación \n            comportamental.<BR>o Priorización de segmentos con mayor potencial \n            comercial.<BR>Taller práctico<BR>o Creación del perfil de cliente \n            ideal con IA.<BR>o Desarrollo de un análisis base de mercado y \n            competencia.<BR><BR><STRONG style="COLOR: rgb(30,58,138)">Módulo 3: \n            Propuesta de Valor, Posicionamiento y Plan Estratégico de \n            Marketing</STRONG><BR>Construcción de la propuesta de valor<BR>o \n            Identificación del problema principal.<BR>o Definición de la promesa \n            de valor.<BR>o Diferenciación competitiva.<BR>o Resultados esperados \n            del cliente.<BR>o Argumentos clave para comunicar \n            valor.<BR>Posicionamiento estratégico<BR>o Desarrollo del mensaje \n            central.<BR>o Ángulos de marketing.<BR>o Storyselling con IA.<BR>o \n            Adaptación del mensaje según público, canal y etapa del \n            funnel.<BR>Construcción del plan estratégico de marketing<BR>o \n            Definición de objetivos comerciales.<BR>o KPIs estratégicos.<BR>o \n            Selección de canales digitales.<BR>o Roadmap estratégico de \n            marketing de 90 días.<BR>o Priorización de acciones según impacto y \n            facilidad de ejecución.<BR>Taller práctico<BR>o Desarrollo de la \n            propuesta de valor.<BR>o Construcción del plan estratégico \n            base.<BR><BR><STRONG style="COLOR: rgb(30,58,138)">Módulo 4: Sistema \n            Digital de Captación y Conversión con IA</STRONG><BR>Arquitectura \n            del funnel de ventas<BR>o Estructura del funnel digital.<BR>o \n            Atracción.<BR>o Captura.<BR>o Nutrición.<BR>o Conversión.<BR>o \n            Fidelización.<BR>o Relación entre marketing, ventas y experiencia \n            del cliente.<BR>Customer journey estratégico<BR>o Puntos de contacto \n            digitales.<BR>o Diseño de la experiencia del cliente.<BR>o Mensajes \n            clave por etapa del recorrido.<BR>o Identificación de fricciones y \n            oportunidades de mejora.<BR>Lead magnets con IA<BR>o Tipos de lead \n            magnets.<BR>o Validación de ideas con IA.<BR>o Creación de lead \n            magnets orientados a conversión.<BR>o Alineación del lead magnet con \n            el cliente ideal y la propuesta de valor.<BR>Landing pages \n            orientadas a conversión<BR>o Elementos de una landing page \n            efectiva.<BR>o Estructura estratégica de una página de \n            captura..<BR>o Copywriting para landing pages con IA.<BR>o \n            Optimización de mensajes, beneficios y llamados a la \n            acción.<BR>Taller práctico<BR>o Diseño del funnel completo.<BR>o \n            Creación de la estructura de una landing page.<BR>o Desarrollo de \n            una propuesta de lead magnet.<BR><BR><STRONG \n            style="COLOR: rgb(30,58,138)">Módulo 5: Email Marketing, WhatsApp y \n            Seguimiento Comercial con IA</STRONG><BR>Email marketing \n            estratégico<BR>o Rol del email dentro del funnel de ventas.<BR>o \n            Tipos de emails: captación, nutrición, conversión y \n            fidelización.<BR>o Diferencia entre campañas puntuales y secuencias \n            de seguimiento.<BR>o Buenas prácticas para mejorar apertura, lectura \n            y respuesta.<BR>o Uso de IA para crear estructuras y versiones de \n            emails.<BR>Secuencias de emails con IA<BR>o Estructura de una \n            secuencia de emails.<BR>o Secuencias clave: bienvenida, nutrición, \n            venta y reactivación.<BR>o Personalización de mensajes según \n            segmento y etapa del prospecto.<BR>o Optimización de asuntos, \n            preheaders y llamados a la acción.<BR>o Adaptación del tono según \n            marca, público y objetivo comercial.<BR>Seguimiento comercial por \n            WhatsApp<BR>o Rol de WhatsApp dentro del proceso de ventas.<BR>o \n            Momentos clave para contactar a un prospecto.<BR>o Mensajes de \n            primer contacto, seguimiento, reactivación y cierre.<BR>o Uso de IA \n            para crear mensajes comerciales más claros y personalizados.<BR>o \n            Buenas prácticas para evitar mensajes invasivos o \n            repetitivos.<BR>Pipeline comercial en WhatsApp<BR>o Qué es un \n            pipeline comercial y por qué ayuda a ordenar el seguimiento.<BR>o \n            Etapas básicas: nuevo lead, contactado, interesado, propuesta \n            enviada, seguimiento, cierre ganado y cierre perdido.<BR>o \n            Clasificación de leads según interés, urgencia y oportunidad \n            comercial.<BR>o Priorización de prospectos y próximos pasos.<BR>o \n            Indicadores básicos: leads activos, tasa de respuesta, propuestas \n            enviadas y cierres.<BR>Taller práctico<BR>o Creación de una \n            secuencia básica de emails.<BR>o Desarrollo de mensajes de \n            seguimiento por WhatsApp.<BR>o Diseño de un pipeline comercial \n            simple.<BR>o Creación de plantillas para objeciones \n            frecuentes.<BR><BR><STRONG style="COLOR: rgb(30,58,138)">Módulo 6: \n            Estrategia de Contenidos, SEO y Redes Sociales con IA</STRONG><BR>1. \n            Estrategia de contenidos orientada a ventas<BR>o Contenido según el \n            funnel: TOFU, MOFU y BOFU.<BR>o Pilares de contenido alineados al \n            cliente ideal y propuesta de valor.<BR>o Diferencia entre contenido \n            educativo, de autoridad, confianza y conversión.<BR>o Relación entre \n            contenido, marca y generación de demanda.<BR>2. Creación de \n            contenido con IA para redes sociales<BR>o Generación de ideas de \n            contenido con IA.<BR>o Creación de posts para redes sociales.<BR>o \n            Adaptación de mensajes por canal y formato.<BR>o Reutilización de \n            contenidos con IA.<BR>3. SEO práctico con IA<BR>o Ideación de temas \n            SEO con IA.<BR>o Estructura básica de artículos optimizados.<BR>o \n            Optimización de títulos, subtítulos y descripciones.<BR>o Creación \n            de contenidos para atraer tráfico calificado.<BR>4. Planificación de \n            contenidos<BR>o Calendario editorial mensual.<BR>o Priorización de \n            contenidos según objetivos comerciales.<BR>o Organización simple del \n            flujo de producción de contenido.<BR>Taller práctico<BR>o Desarrollo \n            de un calendario mensual de contenidos.<BR>o Creación de piezas base \n            para redes sociales.<BR>o Estructura de un artículo SEO.<BR>o \n            Adaptación de una pieza de contenido a distintos \n            formatos.<BR><BR><STRONG style="COLOR: rgb(30,58,138)">Módulo 7: \n            Creatividad Visual, Imágenes y Video Marketing con IA</STRONG><BR>1. \n            Creatividad visual aplicada al marketing<BR>o Traducción de mensajes \n            comerciales en ideas visuales.<BR>o Desarrollo de conceptos \n            creativos para contenidos y campañas.<BR>o Relación entre mensaje, \n            formato y objetivo comercial.<BR>2. Creación de imágenes con IA<BR>o \n            Generación de imágenes con ChatGPT o Gemini.<BR>o Creación de \n            imágenes para redes sociales.<BR>o Variantes visuales simples para \n            pruebas creativas.<BR>3. Video marketing con IA<BR>o Tipos de videos \n            según objetivo: educativo, autoridad, publicitario y \n            conversión.<BR>o Creación de guiones cortos para video con IA.<BR>o \n            Adaptación de una idea visual a formato video.<BR>4. Producción \n            audiovisual básica con IA<BR>o Flujo simple de producción: idea, \n            guion, imagen/video y publicación.<BR>Taller práctico<BR>o \n            Desarrollo de un concepto visual.<BR>o Creación de una imagen base \n            con IA.<BR>o Creación de un guion corto.<BR>o Producción de una \n            pieza audiovisual simple con IA.<BR><BR><STRONG \n            style="COLOR: rgb(30,58,138)">Módulo 8: Publicidad Digital y \n            Analítica con IA</STRONG><BR>Estrategia de campañas digitales<BR>o \n            Arquitectura de campañas digitales.<BR>o Definición de \n            audiencias.<BR>o Ángulos publicitarios.<BR>o Selección de \n            plataformas según objetivo comercial.<BR>o Meta Ads.<BR>o Linkedin \n            Ads.<BR>o Google Ads.<BR>Copywriting publicitario con IA<BR>o Hooks \n            publicitarios.<BR>o Beneficios vs características.<BR>o Llamados a \n            la acción efectivos.<BR>o Creación de variaciones de anuncios con \n            IA.<BR>o Adaptación del copy según plataforma y etapa del \n            funnel.<BR>Creativos publicitarios con IA<BR>o Creación de conceptos \n            visuales.<BR>o Generación de imágenes publicitarias.<BR>o Variantes \n            creativas.<BR>o Relación entre mensaje, formato y objetivo de \n            campaña.<BR>Testing y optimización<BR>o Variaciones de \n            anuncios.<BR>o Introducción al testing A/B.<BR>o Optimización de \n            campañas.<BR>Analítica de marketing con IA<BR>o Marketing basado en \n            datos.<BR>o KPIs clave de marketing: CAC, ROAS, CTR, Conversion Rate \n            y CPL.<BR>o Interpretación de resultados con IA.<BR>Taller práctico \n            final<BR>o Desarrollo de una ficha estratégica de campaña.<BR>o \n            Análisis de métricas y oportunidades de optimización.<BR><BR><STRONG \n            style="COLOR: rgb(30,58,138)">Módulo 9: Análisis de Datos y \n            Estadística Aplicada a Marketing y Ventas con Inteligencia \n            Artificial (DIEGO MIRANDA - CHILE)</STRONG><BR>A) Fundamentos de \n            Datos en Marketing y Ventas<BR>o Introducción al análisis de datos \n            en negocios<BR>o Tipos de datos en marketing:<BR>o Datos de \n            clientes<BR>o Datos de ventas<BR>o Datos de comportamiento<BR>o \n            Principales indicadores (KPIs):<BR>o Ventas totales<BR>o Frecuencia \n            de compra<BR>o Tasa de conversión<BR>o Flujo de valor:<BR>o Datos - \n            Información - Decisiones<BR>Actividad práctica:<BR>o Análisis \n            inicial de un dataset de ventas:<BR>o Identificación de \n            variables<BR>o Cálculo de ventas totales<BR>o Identificación del \n            producto más vendido<BR>B) Análisis Exploratorio de Datos (EDA) \n            aplicado a Negocio<BR>o Estadística descriptiva:<BR>o Media<BR>o \n            Mediana<BR>o Desviación estándar<BR>o Análisis por \n            segmentación:<BR>o Clientes por edad<BR>o Clientes por región<BR>o \n            Clientes por frecuencia de compra<BR>o Visualización de datos:<BR>o \n            Ventas por fecha<BR>o Ventas por producto<BR>o Distribución de \n            clientes<BR>Herramientas:<BR>o Python (Pandas, Matplotlib)<BR>o \n            Actividad práctica:<BR>o Identificación de:<BR>o Clientes frecuentes \n            vs ocasionales<BR>o Productos más rentables<BR>o Días de mayor \n            venta<BR>o Generación de gráficos simples<BR>C) Inteligencia \n            Artificial aplicada a Marketing y Ventas<BR>1. Segmentación de \n            clientes (Clustering)<BR>o Introducción a K-Means<BR>o Agrupación \n            automática de clientes<BR>o Interpretación de segmentos:<BR>o \n            Clientes premium<BR>o Clientes ocasionales<BR>o Clientes sensibles \n            al precio<BR>2. Predicción de ventas<BR>o Introducción a modelos \n            predictivos<BR>o Variables relevantes:<BR>o Tiempo (fecha)<BR>o \n            Promociones<BR>o Historial de ventas<BR>o Modelos simples:<BR>o \n            Regresión<BR>o Árboles de decisión<BR>3. Sistemas de \n            recomendación<BR>o Concepto:<BR>o "Clientes similares compran \n            productos similares"<BR>o Aplicación básica en ventas<BR>Actividad \n            práctica:<BR>o Segmentación de clientes mediante clustering<BR>o \n            Construcción de un modelo simple de predicción<BR>o Interpretación \n            de resultados<BR>D) Toma de Decisiones Basadas en Datos<BR>o \n            Transformación de análisis en estrategias:<BR>o Segmentación de \n            campañas<BR>o Optimización de inventario<BR>o Identificación de \n            oportunidades de venta<BR>o Casos de uso:<BR>o Aumento de \n            ventas<BR>o Reducción de costos<BR>o Mejora de \n            conversión<BR>Herramientas Utilizadas en el curso<BR>o Python \n            (Google Colab recomendado)<BR>o Librerías:<BR>o pandas<BR>o \n            numpy<BR>o matplotlib<BR>o scikit-learn<BR><BR><STRONG \n            style="COLOR: rgb(30,58,138)">Módulo Extra: Vibe Coding para Landing \n            Pages, Webs, E-commerce y CRM con IA</STRONG><BR>1. Introducción al \n            Vibe Coding y criterios de implementación<BR>o Qué es Vibe \n            Coding.<BR>o Cómo crear soluciones digitales usando instrucciones en \n            lenguaje natural.<BR>o Casos de uso en marketing, ventas y captación \n            de clientes.<BR>o Herramientas del módulo: Claude Code, Codex y \n            Antigravity.<BR>o Cuándo usar código directo y cuándo usar \n            WordPress.<BR>o Criterios de decisión: velocidad, flexibilidad, \n            mantenimiento, escalabilidad y nivel de personalización.<BR>2. \n            Creación de Landing Pages con IA<BR>o Estructura de una landing page \n            orientada a conversión.<BR>o Generación de copywriting con IA.<BR>o \n            Creación de formularios y captación de contactos.<BR>o Desarrollo \n            asistido con Claude Code, Codex y Antigravity.<BR>o Optimización \n            básica para campañas y funnels de venta.<BR>3. Creación de una \n            página web corporativa con IA<BR>o Estructura web: inicio, \n            servicios, nosotros, contacto y CTA.<BR>o Arquitectura de navegación \n            y experiencia del usuario.<BR>o Generación de textos, secciones y \n            contenido can IA.<BR>o Adaptación del proyecto a código directo o \n            WordPress.<BR>4. Creación de una tienda online con IA<BR>o \n            Estructura comercial de una tienda online.<BR>o Catálogo, \n            categorías, fichas de producto y carrito.<BR>o Generación de \n            descripciones y contenido de producto con IA.<BR>o Implementación \n            con WordPress o código directo según el caso.<BR>5. Integración de \n            chat web inteligente, CRM e IA<BR>o Diseño del flujo conversacional. \n            <FONT color=#ffffff>contactodestaperapidocl</FONT><BR>o Creación de una base \n            de conocimiento para atención automática.<BR>o Integración del chat \n            en landing pages, webs y tiendas online.<BR>o Captura automática de \n            leads desde formularios y chats.<BR>o Registro y organización de \n            contactos en CRM.<BR>o Clasificación de prospectos y seguimiento \n            comercial con IA.</P></DIV></TD></TR>\n        <TR>\n          <TD \n          style="BORDER-TOP: rgb(226,232,240) 1px solid; PADDING-BOTTOM: 50px; PADDING-TOP: 50px; PADDING-LEFT: 20px; PADDING-RIGHT: 20px; BACKGROUND-COLOR: rgb(239,246,255)" \n          align=center>\n            <P \n            style="FONT-SIZE: 14px; MARGIN-BOTTOM: 25px; TEXT-TRANSFORM: uppercase; COLOR: rgb(30,64,175); LETTER-SPACING: 1px">Inscripciones \n            abiertas vía WhatsApp al<SPAN>&nbsp;</SPAN><SPAN \n            style="FONT-WEIGHT: 900; COLOR: rgb(30,58,138)">+51959117612</SPAN></P><A \n            style="FONT-SIZE: 18px; TEXT-DECORATION: none; 