INSERT INTO "correos" ("id","message_id","de","para","asunto","cuerpo_texto","cuerpo_html","dominio","estado","recibido_en","creado_en","respuesta_borrador","respuesta_enviada","respondido_en","adjunto_nombre","adjunto_b64","notificado","ajuste_pedido","ajuste_enviar","confianza","motivo_revision","dedup_hash","thread_id","in_reply_to","referencias","leido","estado_previo","etiquetas","estado_prev_papelera") VALUES(579,'<F60C44FB64B09E3DE1E4AD1236BB623D@74.48.149.9>','it@thereisnobadnews.com','proyectos@destaperapido.cl','¿Quieres generar Ingresos dictando Cursos Online y promoviéndolos?',replace('BUSCAMOS EXPOSITORES Y SOCIOS PARA CURSOS ONLINE EN LATINOAMERICA \n proyectosdestaperapidocl\nEstamos en búsqueda de expositores en las sgtes áreas y que tenga de preferencia conocimientos en IA:\n- Finanzas con IA\n- Recursos Humanos con IA\n- Inteligencia Artificial (uso y manejo avanzado de herramientas IA)\nDe preferencia con cartera de clientes para si desea programar cursos en sociedad. \nSI ERES EXPERTO EN ESTOS TEMAS DICTA CON NOSOTROS ONLINE:\nDe estar interesa@ enviar su CV y temas de su expertise, que se puedan vender online vía zoom días de semana en las noches. \n\nSI TIENES CONTATOS O CLIENTES GANA HASTA 50% DE LAS VENTAS:\n\nTambién estamos en búsqueda de SOCIOS Y/O ALIADOS ESTRATÉGICOS que deseen obtener Ingresos Extras vendiendo cursos (ofrecemos hasta 50% de los ingresos) o que actualmente estén en el rubro para ayudarles a vender bajo porcentajes sobre la venta.\nDe estar interesa@ por favor contactarnos para explicarle la propuesta de negocio.\nAtentamente,\nRodrigo Alva\nCoordinador Latam\nELC Escuela Latinoamericana de Capacitación\nContactar por Whatsapp al >>> +51998236916 \nE L C  Escuela Latinoamericana de Capacitación\n Deseo conocer la oferta: Click AQUÍ\n\n\n\n\n\n\n\nSi no desea recibir nuestros mensajes puede pedir desuscribirse haciendo click ACA\n\n','\n',char(10)),replace('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0 Transitional//EN">\n<H